INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X01','math',1,'u4',ARRAY['M1-2-u4-C1']::text[],'이어 세기에서 시작 수를 함께 센다 — 7+5 를 「7, 8, 9, 10, 11」로 세어 11이라 함','시작 수는 이미 있는 수임을 손가락을 접으며 「7 다음부터」 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X02','math',1,'u4',ARRAY['M1-2-u4-C1','M1-2-u4-C2','M1-2-u4-C3']::text[],'합이 10을 넘으면 10을 빠뜨리고 낱개만 쓴다 — 7+5=2','십 배열판 윗판이 꽉 찬 것이 10임을 짚고 「10과 2」로 읽게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X03','math',1,'u4',ARRAY['M1-2-u4-C2','M1-2-u4-C3','M1-2-u4-C6','M1-2-u4-C7']::text[],'10이 되도록 가르지 않고 아무 수로나 가른다 — 6+9 에서 9를 3과 6으로','「6과 모아 10이 되는 수」를 먼저 찾게 한 뒤 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X04','math',1,'u4',ARRAY['M1-2-u4-C1','M1-2-u4-C2','M1-2-u4-C3']::text[],'10을 만든 뒤 남은 수를 더하지 않아 답을 10이라 한다','십 배열판 아랫판에 남은 것을 그리게 하고 「10과 몇」으로 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X05','math',1,'u4',ARRAY['M1-2-u4-C2','M1-2-u4-C3']::text[],'가른 수 가운데 한 쪽을 두 번 쓴다 — 6+9 에서 9를 4와 5로 갈라 놓고 10+4=14','가른 두 수에 ○ 표를 하고 하나씩 지워 가며 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X06','math',1,'u4',ARRAY['M1-2-u4-C4']::text[],'더하는 수가 1 커져도 합은 그대로라고 한다 — 8+3=11 이면 8+4 도 11','8+3 줄 밑에 8+4 줄을 그려 하나 더 늘어남을 눈으로 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X07','math',1,'u4',ARRAY['M1-2-u4-C4']::text[],'두 수의 순서를 바꾸면 합이 달라진다고 한다 — 9+3 과 3+9 가 다르다고 함','두 무리를 좌우로 바꿔 놓아도 전체는 그대로임을 세어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X08','math',1,'u4',ARRAY['M1-2-u4-C5']::text[],'거꾸로 세기에서 시작 수를 함께 센다 — 13−5 를 「13, 12, 11, 10, 9」로 세어 9라 함','13 은 있는 수, 12 부터 세게 하기(이어 세기와 같은 이치)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X09','math',1,'u4',ARRAY['M1-2-u4-C5']::text[],'「몇 개 더 많은지」를 두 수를 더해 구한다 — 12와 7 을 19','하나씩 짝 짓고 짝 없이 남는 것만 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X10','math',1,'u4',ARRAY['M1-2-u4-C6','M1-2-u4-C7']::text[],'낱개끼리 뺄 수 없을 때 작은 수에서 큰 수를 거꾸로 뺀다 — 13−8: 8−3=5 → 15','답이 13보다 커졌음을 먼저 보게 하고 10에서 빼기로 돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X11','math',1,'u4',ARRAY['M1-2-u4-C7']::text[],'10에서 뺀 뒤 남은 낱개를 더하지 않는다 — 15−7: 10−7=3 → 3','십 배열판 아랫판의 낱개가 그대로 남아 있음을 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X12','math',1,'u4',ARRAY['M1-2-u4-C6']::text[],'낱개를 뺀 뒤 나머지를 더 빼지 않아 답을 10이라 한다 — 14−9: 14−4=10 → 10','빼는 수 9를 4와 5로 가른 뒤 5에도 ✓ 표를 하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X13','math',1,'u4',ARRAY['M1-2-u4-C8']::text[],'빼는 수가 커지면 차도 커진다고 한다 / 두 수가 함께 커지면 차도 커진다고 한다','12−2, 12−3, 12−4 줄을 그려 남는 것이 줄어드는 것을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u4-X14','math',1,'u4',ARRAY['M1-2-u4-C8']::text[],'덧셈식과 뺄셈식의 관계를 쓰지 못한다 — 7+7=14 를 알아도 14−7 을 다시 센다','모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#1','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',1,'sa','auto','우유갑 7개를 모았는데 5개를 더 가져왔어요. 7부터 5번 이어 세면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":1,"kind":"sa","stem":"우유갑 7개를 모았는데 5개를 더 가져왔어요. 7부터 5번 이어 세면 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":7,"steps":5,"dir":"up"},"answer":["12"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["7은 이미 있는 수예요 — 8부터 세어요.","8, 9, 10, 11, 12 — 5번 이어 세면 12예요.","7부터 세면 11이 되어 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#2','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',1,'mc','auto','십 배열판을 보세요. 8개가 있었는데 5개를 더 놓았어요. 모두 몇 개인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 8개가 있었는데 5개를 더 놓았어요. 모두 몇 개인가요?","asset":{"type":"ten_frames2","top":8,"bottom":3,"add":2},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 8에 2를 더 놓아 10이 되었어요.","아랫판에 남은 3을 놓았으니 10과 3, 13이에요.","10에서 멈추거나 3만 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#3','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',1,'mc','auto','수 구슬을 9개 옮기고 4개를 더 옮겼어요. 옮긴 구슬은 모두 몇 개인가요?',ARRAY['M1-2-u4-X01','M1-2-u4-X02']::text[],false,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"수 구슬을 9개 옮기고 4개를 더 옮겼어요. 옮긴 구슬은 모두 몇 개인가요?","asset":{"type":"beads","moved":13},"options":[{"t":"13","correct":true},{"t":"12","mis":"M1-2-u4-X01"},{"t":"3","mis":"M1-2-u4-X02"}],"explanation":["9개 다음에 10, 11, 12, 13 — 4개를 더 옮겼어요.","모두 13개예요 — 9 + 4 = 13.","9를 함께 세면 12가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#4','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',1,'mc','auto','요구르트병 6개와 5개를 모았어요. 모두 몇 개인지 바르게 쓴 식은 어느 것인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],false,'{"seq":4,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"요구르트병 6개와 5개를 모았어요. 모두 몇 개인지 바르게 쓴 식은 어느 것인가요?","options":[{"t":"6 + 5 = 11","correct":true},{"t":"6 + 5 = 10","mis":"M1-2-u4-X04"},{"t":"6 + 5 = 1","mis":"M1-2-u4-X02"}],"explanation":["모으기는 덧셈이에요 — 6 + 5.","6부터 5번 이어 세면 7, 8, 9, 10, 11이에요.","10에서 멈추거나 낱개 1만 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#5','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',2,'ox','auto','7부터 6번 이어 세면 12입니다.',ARRAY['M1-2-u4-X01']::text[],true,'{"seq":5,"concept":"M1-2-u4-C1","difficulty":2,"kind":"ox","stem":"7부터 6번 이어 세면 12입니다.","asset":{"type":"count_on","start":7,"steps":6,"dir":"up"},"answer":"X","reason_options":[{"t":"8부터 6번 세면 13이니까","correct":true},{"t":"7부터 세어도 되니까","mis":"M1-2-u4-X01"}],"variant_rule":{"counton":{"dir":"up"}},"explanation":["7은 이미 있는 수라 8부터 세어요.","8, 9, 10, 11, 12, 13 — 답은 13이에요.","7을 함께 세면 12가 나와요 — 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#6','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',2,'sa','auto','십 배열판을 보세요. 7 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u4-C1","difficulty":2,"kind":"sa","stem":"십 배열판을 보세요. 7 + 7 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"ten_frames2","top":7,"bottom":4,"add":3},"answer":["14"],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 7에 3을 더 놓아 10이 되었어요.","아랫판에 남은 4를 놓았으니 14예요.","윗판 10과 아랫판 4를 합쳐 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#7','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',2,'mc','auto','꽃이 9송이 피어 있는데 3송이가 더 피었어요. 모두 몇 송이인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":7,"concept":"M1-2-u4-C1","difficulty":2,"kind":"mc","stem":"꽃이 9송이 피어 있는데 3송이가 더 피었어요. 모두 몇 송이인가요?","options":[{"t":"12","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"2","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["9부터 3번 이어 세면 10, 11, 12예요.","9 + 3 = 12 예요.","10에서 멈추면 안 되고, 2라고만 쓰면 10을 빠뜨린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#8','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',2,'match','auto','상황과 덧셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C1","difficulty":2,"kind":"match","stem":"상황과 덧셈식을 선으로 이어 보세요.","pairs":[{"l":"우유갑 8개와 6개를 모았어요","r":"8 + 6"},{"l":"꽃 7송이와 9송이가 피었어요","r":"7 + 9"},{"l":"동전 5개에 7개를 더 넣었어요","r":"5 + 7"}],"explanation":["모으거나 더 넣는 상황은 덧셈이에요.","앞의 수와 뒤의 수를 그대로 식에 써요.","8 + 6 = 14, 7 + 9 = 16, 5 + 7 = 12 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#9','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',2,'blank','auto','6 + 8 = □ 예요. 6부터 8번 이어 세어 □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X01','M1-2-u4-X02']::text[],false,'{"seq":9,"concept":"M1-2-u4-C1","difficulty":2,"kind":"blank","stem":"6 + 8 = □ 예요. 6부터 8번 이어 세어 □ 안에 알맞은 수를 고르세요.","options":[{"t":"14","correct":true},{"t":"13","mis":"M1-2-u4-X01"},{"t":"4","mis":"M1-2-u4-X02"}],"explanation":["7부터 8번 세면 7, 8, 9, 10, 11, 12, 13, 14예요.","6 + 8 = 14 예요.","6을 함께 세면 13이 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_basic#10','math',1,2,'u4','L02','g1_2_math_u4_L02_basic','lesson_basic','M1-2-u4-C1',3,'error','auto','지우가 8 + 5 를 이어 세었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#1','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',2,'sa','auto','6부터 7번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":2,"kind":"sa","stem":"6부터 7번 이어 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":6,"steps":7,"dir":"up"},"answer":["13"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["6은 이미 있는 수예요 — 7부터 세어요.","7, 8, 9, 10, 11, 12, 13 — 7번 세면 13이에요.","6부터 세면 12가 나와요 — 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#2','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',2,'mc','auto','수 구슬을 8개 옮긴 다음 7개를 더 옮겼어요. 옮긴 구슬은 모두 몇 개인가요?',ARRAY['M1-2-u4-X01','M1-2-u4-X02']::text[],false,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":2,"kind":"mc","stem":"수 구슬을 8개 옮긴 다음 7개를 더 옮겼어요. 옮긴 구슬은 모두 몇 개인가요?","asset":{"type":"beads","moved":15},"options":[{"t":"15","correct":true},{"t":"14","mis":"M1-2-u4-X01"},{"t":"5","mis":"M1-2-u4-X02"}],"explanation":["8개 다음에 9, 10, 11, 12, 13, 14, 15 — 7개를 더 옮겼어요.","8 + 7 = 15 예요.","8을 함께 세면 14, 낱개 5만 읽으면 10이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#3','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',3,'ox','auto','십 배열판을 보세요. 9 + 7 = 16 입니다.',ARRAY['M1-2-u4-X04']::text[],true,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":3,"kind":"ox","stem":"십 배열판을 보세요. 9 + 7 = 16 입니다.","asset":{"type":"ten_frames2","top":9,"bottom":6,"add":1},"answer":"O","reason_options":[{"t":"윗판 10과 아랫판 6을 합쳐 세니까","correct":true},{"t":"윗판 10만 세면 되니까","mis":"M1-2-u4-X04"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["9에 1을 더 놓아 윗판이 10이 되었어요.","아랫판에 6이 있으니 10과 6, 16이에요 — 맞아요.","윗판만 세고 끝내면 6이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#4','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',3,'sa','auto','우유갑 7개와 요구르트병 8개를 재활용 상자에 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u4-C1","difficulty":3,"kind":"sa","stem":"우유갑 7개와 요구르트병 8개를 재활용 상자에 모았어요. 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["모으기는 덧셈이에요 — 7 + 8.","7부터 8번 이어 세거나 7 + 3 + 5 로 10을 만들면 15예요.","종류가 달라도 「모두 몇 개」는 더해서 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#5','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',3,'mc','auto','8 + 6 을 이어 세어 구해요. 8 다음에 세는 수를 차례로 바르게 쓴 것은 어느 것인가요?',ARRAY['M1-2-u4-X01','M1-2-u4-X04']::text[],false,'{"seq":5,"concept":"M1-2-u4-C1","difficulty":3,"kind":"mc","stem":"8 + 6 을 이어 세어 구해요. 8 다음에 세는 수를 차례로 바르게 쓴 것은 어느 것인가요?","options":[{"t":"9, 10, 11, 12, 13, 14","correct":true},{"t":"8, 9, 10, 11, 12, 13","mis":"M1-2-u4-X01"},{"t":"9, 10","mis":"M1-2-u4-X04"}],"explanation":["8은 이미 있는 수라 9부터 세어요.","6번 세면 9, 10, 11, 12, 13, 14 — 답은 14예요.","8부터 세면 13이 되고, 10에서 멈추면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#6','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',3,'error','auto','민수가 9 + 4 를 이렇게 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#7','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',3,'match','auto','덧셈식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C1","difficulty":3,"kind":"match","stem":"덧셈식과 답을 선으로 이어 보세요.","pairs":[{"l":"7 + 5","r":"12"},{"l":"8 + 8","r":"16"},{"l":"6 + 8","r":"14"}],"explanation":["7 + 5 는 7부터 5번 이어 세어 12예요.","8 + 8 = 16, 6 + 8 = 14 예요.","10을 먼저 만들어 확인해도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#8','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',4,'sa','auto','□ + 6 = 13 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C1","difficulty":4,"kind":"sa","stem":"□ + 6 = 13 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["7"],"explanation":["13은 10과 3이에요.","6에 4를 더하면 10, 10에 3을 더하면 13 — 그래서 □는 4와 3을 모은 7이에요.","7 + 6 = 13 으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#9','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',4,'mc','auto','우유갑이 9개 있었는데 몇 개를 더 모았더니 15개가 되었어요. 더 모은 우유갑은 몇 개인가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X01']::text[],false,'{"seq":9,"concept":"M1-2-u4-C1","difficulty":4,"kind":"mc","stem":"우유갑이 9개 있었는데 몇 개를 더 모았더니 15개가 되었어요. 더 모은 우유갑은 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"24","mis":"M1-2-u4-X09"},{"t":"5","mis":"M1-2-u4-X01"}],"explanation":["9에서 15까지 이어 세면 10, 11, 12, 13, 14, 15 — 6번이에요.","9 + 6 = 15 예요.","9와 15를 더한 24는 「더 모은 수」가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L02_challenge#10','math',1,2,'u4','L02','g1_2_math_u4_L02_challenge','lesson_challenge','M1-2-u4-C1',4,'essay','teacher','7 + 6 을 이어 세기와 십 배열판, 두 가지 방법으로 구하는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C1","difficulty":4,"kind":"essay","stem":"7 + 6 을 이어 세기와 십 배열판, 두 가지 방법으로 구하는 방법을 쓰세요.","answer_guide":"① 이어 세기: 8부터 6번 세어 13 (7을 함께 세지 않음) ② 십 배열판: 7에 3을 놓아 10, 남은 3을 아랫판에 놓아 13 ③ 두 답이 같다 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["이어 세기는 7 다음 8부터 6번 세어 13이에요.","십 배열판은 7에 3을 더 놓아 10을 만들고 남은 3을 더해 13이에요.","방법이 달라도 답은 13으로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#1','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',1,'mc','auto','우유갑 집을 초록 지붕 6개, 노랑 지붕 9개 만들었어요. 6과 더해 10을 만들려고 9를 4와 몇으로 갈랐나요?',ARRAY['M1-2-u4-X03','M1-2-u4-X05']::text[],true,'{"seq":1,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"우유갑 집을 초록 지붕 6개, 노랑 지붕 9개 만들었어요. 6과 더해 10을 만들려고 9를 4와 몇으로 갈랐나요?","asset":{"type":"split_tree","left":6,"right":9,"op":"+","split":"right","parts":[4,null]},"options":[{"t":"5","correct":true},{"t":"4","mis":"M1-2-u4-X03"},{"t":"9","mis":"M1-2-u4-X05"}],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["6과 4를 더하면 10이에요.","9에서 4를 떼면 5가 남아요.","9는 4와 5로 갈라져요 — 아무 수로나 가르면 10이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#2','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',1,'sa','auto','십 배열판을 보세요. 6개가 있었는데 9개를 더 놓았어요. 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u4-C2","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 6개가 있었는데 9개를 더 놓았어요. 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"ten_frames2","top":6,"add":4,"bottom":5},"answer":["15"],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 6에 4를 더 놓아 10이 되었어요.","아랫판에 남은 5를 놓았으니 10과 5, 15예요.","윗판이 꽉 찼으면 10, 아랫판까지 세어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#3','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',1,'mc','auto','7과 더해 10이 되는 수는 무엇인가요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":3,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"7과 더해 10이 되는 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M1-2-u4-X03"},{"t":"7","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["7 + 3 = 10 이에요.","4를 더하면 11, 7을 더하면 14가 돼요.","10이 되는 짝(1과 9, 2와 8, 3과 7, 4와 6, 5와 5)을 외워 두세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#4','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',1,'blank','auto','8 + 5 = 8 + 2 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":1,"kind":"blank","stem":"8 + 5 = 8 + 2 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-2-u4-X05"},{"t":"2","mis":"M1-2-u4-X03"}],"explanation":["8과 더해 10이 되도록 5를 2와 3으로 갈랐어요.","2는 이미 썼으니 남은 3을 더해요.","5를 2와 3으로 가른 것을 잊지 마세요 — 5를 그대로 또 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#5','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',2,'sa','auto','9 + 4 는 얼마인가요? 10을 먼저 만들어 계산하고 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"9 + 4 는 얼마인가요? 10을 먼저 만들어 계산하고 숫자로 쓰세요.","answer":["13"],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["9와 1을 더하면 10이니까 4를 1과 3으로 갈라요.","10에 남은 3을 더하면 13이에요.","10을 만들고 나서 남은 수를 꼭 더하세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#6','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',2,'mc','auto','5 + 8 을 10을 만들어 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":6,"concept":"M1-2-u4-C2","difficulty":2,"kind":"mc","stem":"5 + 8 을 10을 만들어 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":5,"right":8,"op":"+","split":"left","parts":[2,3]},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["8과 2를 더해 10을 만들려고 5를 2와 3으로 갈랐어요.","10에 남은 3을 더하면 13이에요.","10에서 멈추면 안 되고, 13을 3이라고만 쓰면 10을 빠뜨린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#7','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',2,'ox','auto','6 + 7 = 13 입니다.',ARRAY['M1-2-u4-X04']::text[],true,'{"seq":7,"concept":"M1-2-u4-C2","difficulty":2,"kind":"ox","stem":"6 + 7 = 13 입니다.","answer":"O","reason_options":[{"t":"6과 4를 더해 10을 만들고 남은 3을 더했으니까","correct":true},{"t":"10만 만들면 계산이 끝나니까","mis":"M1-2-u4-X04"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["6과 4를 더해 10을 만들려고 7을 4와 3으로 갈라요.","10에 3을 더하면 13이에요 — 맞아요.","10만 만들고 끝내면 남은 3이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#8','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',2,'match','auto','식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C2","difficulty":2,"kind":"match","stem":"식과 답을 선으로 이어 보세요.","pairs":[{"l":"7 + 6","r":"13"},{"l":"8 + 8","r":"16"},{"l":"9 + 5","r":"14"}],"explanation":["7 + 6 은 7 + 3 + 3 = 13 이에요.","8 + 8 은 8 + 2 + 6 = 16, 9 + 5 는 9 + 1 + 4 = 14 예요.","세 식 모두 10을 먼저 만들면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#9','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',2,'error','auto','지우가 6 + 9 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_basic#10','math',1,2,'u4','L03','g1_2_math_u4_L03_basic','lesson_basic','M1-2-u4-C2',3,'essay','teacher','8 + 7 을 10을 만들어 계산하는 방법을 쓰세요. 7을 왜 2와 5로 갈랐는지도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C2","difficulty":3,"kind":"essay","stem":"8 + 7 을 10을 만들어 계산하는 방법을 쓰세요. 7을 왜 2와 5로 갈랐는지도 함께 쓰세요.","answer_guide":"① 8과 2를 더해 10을 만든다 ② 남은 5를 더해 15 ③ 8과 모아 10이 되는 수가 2이기 때문에 7을 2와 5로 갈랐다 — 세 가지가 들어 있으면 만점, 답 15만 쓰면 절반","explanation":["8과 더해 10이 되는 수가 2라서 7을 2와 5로 갈라요.","8 + 2 = 10, 10 + 5 = 15 예요.","「10이 되는 짝」을 찾는 것이 가르기의 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#1','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',2,'sa','auto','십 배열판을 보세요. 8 + 8 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"십 배열판을 보세요. 8 + 8 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"ten_frames2","top":8,"add":2,"bottom":6},"answer":["16"],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["8에 2를 더 놓아 윗판을 10으로 채웠어요.","아랫판에 남은 6을 놓았으니 16이에요.","윗판 10과 아랫판을 합쳐 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#2','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',2,'mc','auto','7 + 5 를 계산해요. 7과 더해 10을 만들려면 5를 몇과 몇으로 갈라야 하나요?',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":2,"concept":"M1-2-u4-C2","difficulty":2,"kind":"mc","stem":"7 + 5 를 계산해요. 7과 더해 10을 만들려면 5를 몇과 몇으로 갈라야 하나요?","options":[{"t":"3과 2","correct":true},{"t":"4와 1","mis":"M1-2-u4-X03"},{"t":"1과 4","mis":"M1-2-u4-X03"}],"explanation":["7과 3을 더하면 10이에요.","그래서 5를 3과 2로 갈라요 — 10 + 2 = 12.","4와 1로 가르면 7 + 4 = 11 이라 10이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#3','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',3,'mc','auto','6 + 8 을 10을 만들어 계산하려고 해요. 바르게 가른 것은 어느 것인가요?',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":3,"concept":"M1-2-u4-C2","difficulty":3,"kind":"mc","stem":"6 + 8 을 10을 만들어 계산하려고 해요. 바르게 가른 것은 어느 것인가요?","options":[{"t":"8을 4와 4로","correct":true},{"t":"8을 3과 5로","mis":"M1-2-u4-X03"},{"t":"8을 2와 6으로","mis":"M1-2-u4-X03"}],"explanation":["6과 더해 10이 되는 수는 4예요.","그래서 8을 4와 4로 갈라야 해요 — 6 + 4 = 10, 10 + 4 = 14.","3과 5, 2와 6으로 가르면 6과 더해 10이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#4','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',3,'ox','auto','9 + 6 을 계산할 때 6을 1과 5로 갈라 9 + 1 = 10, 10 + 5 = 15 로 해도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":3,"kind":"ox","stem":"9 + 6 을 계산할 때 6을 1과 5로 갈라 9 + 1 = 10, 10 + 5 = 15 로 해도 됩니다.","answer":"O","reason_options":[{"t":"9와 모아 10이 되는 수 1을 떼어 냈으니까","correct":true},{"t":"가르기는 정해진 수로만 해야 하니까","mis":"M1-2-u4-X03"}],"explanation":["9와 모아 10이 되는 수는 1이에요.","그래서 6을 1과 5로 가른 것은 맞아요 — 답 15.","가르기는 앞 수·뒤 수 어느 쪽이든 10이 되게만 하면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#5','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',3,'sa','auto','7 + 6 에서 7과 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":3,"kind":"sa","stem":"7 + 6 에서 7과 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":7,"right":6,"op":"+","split":"right","parts":[null,3]},"answer":["3"],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["7과 3을 더하면 10이에요.","그래서 6에서 3을 떼어 내요 — 남은 3은 10에 더해요.","7 + 3 = 10, 10 + 3 = 13 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#6','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',3,'error','auto','민수가 8 + 6 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#7','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',3,'data','auto','표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X06','M1-2-u4-X02']::text[],false,'{"seq":7,"concept":"M1-2-u4-C2","difficulty":3,"kind":"data","stem":"표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","asset":{"type":"expr_grid","rows":[["6 + 5","7 + 5","8 + 5"],["11","12",null]]},"options":[{"t":"13","correct":true},{"t":"12","mis":"M1-2-u4-X06"},{"t":"3","mis":"M1-2-u4-X02"}],"explanation":["6 + 5 = 11, 7 + 5 = 12 — 앞 수가 1 커지면 합도 1 커져요.","그래서 8 + 5 = 13 이에요.","10을 만들어 확인하면 8 + 2 + 3 = 13 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#8','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',4,'sa','auto','9 + □ = 15 예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C2","difficulty":4,"kind":"sa","stem":"9 + □ = 15 예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["6"],"explanation":["9와 1을 더하면 10이고, 15는 10과 5예요.","그래서 □는 1과 5를 모은 6이에요 — 9 + 6 = 15.","거꾸로 15에서 9를 빼는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#9','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',4,'mc','auto','7 + 8 과 합이 같은 식은 어느 것인가요?',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":9,"concept":"M1-2-u4-C2","difficulty":4,"kind":"mc","stem":"7 + 8 과 합이 같은 식은 어느 것인가요?","options":[{"t":"9 + 6","correct":true},{"t":"8 + 8","mis":"M1-2-u4-X06"},{"t":"7 + 7","mis":"M1-2-u4-X06"}],"explanation":["7 + 8 = 15 예요.","9 + 6 = 15 로 합이 같아요.","8 + 8 = 16, 7 + 7 = 14 예요 — 1씩 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L03_challenge#10','math',1,2,'u4','L03','g1_2_math_u4_L03_challenge','lesson_challenge','M1-2-u4-C2',4,'essay','teacher','친구가 5 + 9 를 계산할 때 어느 수를 갈라야 하냐고 물었어요. 5를 갈라도 되고 9를 갈라도 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C2","difficulty":4,"kind":"essay","stem":"친구가 5 + 9 를 계산할 때 어느 수를 갈라야 하냐고 물었어요. 5를 갈라도 되고 9를 갈라도 되는 까닭을 쓰세요.","answer_guide":"① 두 방법(5 가르기 · 9 가르기)을 모두 식으로 쓰고 ② 답이 14로 같다는 것 ③ 「10이 되게 가르면 어느 쪽이든 된다」는 까닭 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["9와 더해 10을 만들려면 5를 1과 4로 갈라요 — 10 + 4 = 14.","5와 더해 10을 만들려면 9를 5와 4로 갈라요 — 10 + 4 = 14.","어느 쪽을 갈라도 10을 만들고 남은 수를 더하면 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#1','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',1,'mc','auto','9 + 4 를 계산하려고 9를 갈랐어요. 4와 더해 10을 만들고 남은 수를 더하면 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":1,"concept":"M1-2-u4-C3","difficulty":1,"kind":"mc","stem":"9 + 4 를 계산하려고 9를 갈랐어요. 4와 더해 10을 만들고 남은 수를 더하면 얼마인가요?","asset":{"type":"split_tree","left":9,"right":4,"op":"+","split":"left","parts":[6,3]},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["4와 6을 더하면 10이라 9를 6과 3으로 갈랐어요.","10에 남은 3을 더하면 13이에요.","앞 수를 갈라도 10을 만들고 남은 수를 더하면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#2','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',1,'mc','auto','8 + 7 을 계산해요. 8과 더해 10을 만들려고 7을 2와 몇으로 갈라야 하나요?',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],true,'{"seq":2,"concept":"M1-2-u4-C3","difficulty":1,"kind":"mc","stem":"8 + 7 을 계산해요. 8과 더해 10을 만들려고 7을 2와 몇으로 갈라야 하나요?","asset":{"type":"split_tree","left":8,"right":7,"op":"+","split":"right","parts":[2,null]},"options":[{"t":"5","correct":true},{"t":"2","mis":"M1-2-u4-X05"},{"t":"3","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["8과 2를 더하면 10이에요.","7에서 2를 떼면 5가 남아요.","7은 2와 5로 갈라져요 — 10 + 5 = 15."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#3','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',1,'sa','auto','5 + 9 에서 9와 더해 10을 만들려면 5에서 얼마를 떼어 내야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u4-C3","difficulty":1,"kind":"sa","stem":"5 + 9 에서 9와 더해 10을 만들려면 5에서 얼마를 떼어 내야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":5,"right":9,"op":"+","split":"left","parts":[null,4]},"answer":["1"],"variant_rule":{"maketen2":{"ask":"split","which":"left"}},"explanation":["9와 모아 10이 되는 수는 1이에요.","그래서 5를 1과 4로 갈라요 — 9 + 1 = 10.","남은 4를 10에 더하면 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#4','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',1,'ox','auto','7 + 8 을 계산할 때 7을 갈라도 되고 8을 갈라도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":4,"concept":"M1-2-u4-C3","difficulty":1,"kind":"ox","stem":"7 + 8 을 계산할 때 7을 갈라도 되고 8을 갈라도 됩니다.","answer":"O","reason_options":[{"t":"어느 쪽이든 10이 되게 가르면 되니까","correct":true},{"t":"뒤에 있는 수만 갈라야 하니까","mis":"M1-2-u4-X03"}],"explanation":["8과 모아 10이 되도록 7을 2와 5로 갈라도 돼요 — 10 + 5 = 15.","7과 모아 10이 되도록 8을 3과 5로 갈라도 돼요 — 10 + 5 = 15.","어느 수를 갈라도 답은 15로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#5','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',2,'sa','auto','6 + 9 를 6을 갈라서 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C3","difficulty":2,"kind":"sa","stem":"6 + 9 를 6을 갈라서 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["15"],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["9와 모아 10이 되는 수는 1이라 6을 1과 5로 갈라요.","9 + 1 = 10, 10 + 5 = 15 예요.","앞 수를 갈라도 10을 만들고 남은 수를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#6','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',2,'mc','auto','8 + 5 를 계산해요. 8과 더해 10을 만들려면 5를 몇과 몇으로 갈라야 하나요?',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":6,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"8 + 5 를 계산해요. 8과 더해 10을 만들려면 5를 몇과 몇으로 갈라야 하나요?","options":[{"t":"2와 3","correct":true},{"t":"1과 4","mis":"M1-2-u4-X03"},{"t":"4와 1","mis":"M1-2-u4-X03"}],"explanation":["8과 2를 더하면 10이에요.","그래서 5를 2와 3으로 갈라요 — 10 + 3 = 13.","1과 4로 가르면 8 + 1 = 9 라서 10이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#7','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',2,'blank','auto','9 + 6 을 9를 갈라 계산해요. 9 = 4 + □, 6 + 4 = 10, 10 + □ = 15 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":7,"concept":"M1-2-u4-C3","difficulty":2,"kind":"blank","stem":"9 + 6 을 9를 갈라 계산해요. 9 = 4 + □, 6 + 4 = 10, 10 + □ = 15 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-2-u4-X05"},{"t":"6","mis":"M1-2-u4-X03"}],"explanation":["6과 4를 더하면 10이라 9를 4와 5로 갈랐어요.","4는 이미 썼으니 남은 5를 10에 더해요 — 15.","가른 두 수 가운데 한 쪽만 더하고 나머지는 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#8','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',2,'mc','auto','십 배열판을 보세요. 4 + 8 은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 4 + 8 은 얼마인가요?","asset":{"type":"ten_frames2","top":4,"bottom":2,"add":6},"options":[{"t":"12","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"2","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"both"}},"explanation":["4와 더해 10이 되도록 8을 6과 2로 갈랐어요.","윗판이 10, 아랫판이 2 — 12예요.","아랫판의 2를 빠뜨리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#9','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',2,'match','auto','덧셈식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":2,"kind":"match","stem":"덧셈식과 답을 선으로 이어 보세요.","pairs":[{"l":"9 + 7","r":"16"},{"l":"8 + 6","r":"14"},{"l":"5 + 8","r":"13"}],"explanation":["9 + 7 은 9 + 1 + 6 = 16 이에요.","8 + 6 은 8 + 2 + 4 = 14, 5 + 8 은 5 + 5 + 3 = 13 이에요.","어느 수를 가르든 10을 먼저 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_basic#10','math',1,2,'u4','L04','g1_2_math_u4_L04_basic','lesson_basic','M1-2-u4-C3',3,'error','auto','지우가 7 + 6 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#1','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',2,'sa','auto','8 + 4 를 8을 갈라서 계산했어요. 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C3","difficulty":2,"kind":"sa","stem":"8 + 4 를 8을 갈라서 계산했어요. 답은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":8,"right":4,"op":"+","split":"left","parts":[6,2]},"answer":["12"],"variant_rule":{"maketen2":{"ask":"sum","which":"both"}},"explanation":["4와 모아 10이 되는 수는 6이라 8을 6과 2로 갈라요.","4 + 6 = 10, 10 + 2 = 12 예요.","앞 수를 갈라도 답은 12로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#2','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',2,'mc','auto','6 + 7 을 계산해요. 6과 더해 10을 만들려면 7에서 얼마를 떼어 내야 하나요?',ARRAY['M1-2-u4-X03','M1-2-u4-X05']::text[],true,'{"seq":2,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"6 + 7 을 계산해요. 6과 더해 10을 만들려면 7에서 얼마를 떼어 내야 하나요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-2-u4-X03"},{"t":"6","mis":"M1-2-u4-X05"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["6과 모아 10이 되는 수는 4예요.","7에서 4를 떼면 3이 남아요 — 10 + 3 = 13.","떼어 내는 수는 「6과 모아 10이 되는 수」로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#3','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',3,'ox','auto','5 + 8 에서 8을 5와 3으로 갈라 5 + 5 = 10, 10 + 3 = 13 으로 계산해도 됩니다.',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":3,"concept":"M1-2-u4-C3","difficulty":3,"kind":"ox","stem":"5 + 8 에서 8을 5와 3으로 갈라 5 + 5 = 10, 10 + 3 = 13 으로 계산해도 됩니다.","answer":"O","reason_options":[{"t":"5와 모아 10이 되는 5를 떼어 냈으니까","correct":true},{"t":"앞의 수를 갈라야만 하니까","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"rest","which":"both"}},"explanation":["5와 모아 10이 되는 수는 5예요.","그래서 8을 5와 3으로 가른 것은 맞아요 — 답 13.","5를 2와 3으로 갈라 8 + 2 + 3 으로 해도 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#4','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',3,'mc','auto','9 + 8 을 10을 만들어 계산할 때 바르게 가른 것은 어느 것인가요?',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":4,"concept":"M1-2-u4-C3","difficulty":3,"kind":"mc","stem":"9 + 8 을 10을 만들어 계산할 때 바르게 가른 것은 어느 것인가요?","options":[{"t":"8을 1과 7로","correct":true},{"t":"9를 1과 8로","mis":"M1-2-u4-X03"},{"t":"8을 4와 4로","mis":"M1-2-u4-X03"}],"explanation":["9와 모아 10이 되는 수는 1이라 8을 1과 7로 갈라요.","9 + 1 = 10, 10 + 7 = 17 이에요.","9를 가르려면 8과 모아 10이 되는 2를 떼어 2와 7로 갈라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#5','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',3,'sa','auto','6 + 8 을 6을 갈라서 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C3","difficulty":3,"kind":"sa","stem":"6 + 8 을 6을 갈라서 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["14"],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["8과 모아 10이 되는 수는 2라 6을 2와 4로 갈라요.","8 + 2 = 10, 10 + 4 = 14 예요.","6 + 8 은 8을 4와 4로 갈라도 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#6','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',3,'error','auto','민수가 4 + 9 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#7','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',3,'match','auto','가르는 방법과 가른 결과를 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C3","difficulty":3,"kind":"match","stem":"가르는 방법과 가른 결과를 선으로 이어 보세요.","pairs":[{"l":"9 + 6 에서 9를 가르면","r":"9 = 4 + 5"},{"l":"9 + 6 에서 6을 가르면","r":"6 = 1 + 5"},{"l":"7 + 8 에서 8을 가르면","r":"8 = 3 + 5"}],"explanation":["9를 가르면 6과 모아 10이 되는 4를 떼어 4와 5예요.","6을 가르면 9와 모아 10이 되는 1을 떼어 1과 5예요.","7 + 8 에서 8을 가르면 7과 모아 10이 되는 3을 떼어 3과 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#8','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',4,'sa','auto','어떤 수와 8을 더했더니 15가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":4,"kind":"sa","stem":"어떤 수와 8을 더했더니 15가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["15는 10과 5예요.","8에 2를 더하면 10, 10에 5를 더하면 15 — 그래서 어떤 수는 2와 5를 모은 7이에요.","7 + 8 = 15 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#9','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',4,'mc','auto','8 + 8 을 8을 2와 6으로 갈라 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":4,"kind":"mc","stem":"8 + 8 을 8을 2와 6으로 갈라 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":8,"right":8,"op":"+","split":"right","parts":[2,6]},"options":[{"t":"16","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"6","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"both"}},"explanation":["8과 모아 10이 되도록 다른 8을 2와 6으로 갈랐어요.","8 + 2 = 10, 10 + 6 = 16 이에요.","10에서 멈추거나 6만 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L04_challenge#10','math',1,2,'u4','L04','g1_2_math_u4_L04_challenge','lesson_challenge','M1-2-u4-C3',4,'essay','teacher','6 + 9 를 6을 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 어느 쪽이 더 쉬웠는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C3","difficulty":4,"kind":"essay","stem":"6 + 9 를 6을 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 어느 쪽이 더 쉬웠는지 까닭과 함께 쓰세요.","answer_guide":"① 6을 갈라 9 + 1 = 10, 10 + 5 = 15 ② 9를 갈라 6 + 4 = 10, 10 + 5 = 15 ③ 답이 같다는 것과 자기가 고른 방법의 까닭(예: 9는 1만 더하면 10이라 쉽다) — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["6을 가르면 9와 모아 10이 되는 1을 떼어 9 + 1 + 5 = 15 예요.","9를 가르면 6과 모아 10이 되는 4를 떼어 6 + 4 + 5 = 15 예요.","어느 쪽이든 답은 같고, 10이 되는 짝이 바로 보이는 쪽을 고르면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#1','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',1,'sa','auto','표를 보세요. 8 + 3 = 11 이에요. 그러면 8 + 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C4","difficulty":1,"kind":"sa","stem":"표를 보세요. 8 + 3 = 11 이에요. 그러면 8 + 4 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["8 + 3","8 + 4"],["11",null]]},"answer":["12"],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["8 + 3 = 11 이에요. 더하는 수 3이 4로 1 커졌어요.","그래서 합도 1 커져 12예요.","다시 세지 않아도 규칙으로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#2','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',1,'mc','auto','7 + 7 = 14 예요. 그러면 7 + 8 은 얼마인가요?',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":2,"concept":"M1-2-u4-C4","difficulty":1,"kind":"mc","stem":"7 + 7 = 14 예요. 그러면 7 + 8 은 얼마인가요?","options":[{"t":"15","correct":true},{"t":"14","mis":"M1-2-u4-X06"},{"t":"13","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"double"}},"explanation":["7 + 8 은 7 + 7 보다 1 큰 수를 더해요.","그래서 14보다 1 큰 15예요.","같은 수를 더한 답에 1을 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#3','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',1,'ox','auto','9 + 3 과 3 + 9 의 합은 같습니다.',ARRAY['M1-2-u4-X07']::text[],true,'{"seq":3,"concept":"M1-2-u4-C4","difficulty":1,"kind":"ox","stem":"9 + 3 과 3 + 9 의 합은 같습니다.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"순서가 바뀌면 합도 달라지니까","mis":"M1-2-u4-X07"}],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["9 + 3 = 12, 3 + 9 = 12 예요.","두 무리를 좌우로 바꿔 놓아도 전체 개수는 같아요.","바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#4','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',1,'mc','auto','표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X06','M1-2-u4-X02']::text[],true,'{"seq":4,"concept":"M1-2-u4-C4","difficulty":1,"kind":"mc","stem":"표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","asset":{"type":"expr_grid","rows":[["6 + 6","6 + 7","6 + 8"],["12","13",null]]},"options":[{"t":"14","correct":true},{"t":"13","mis":"M1-2-u4-X06"},{"t":"4","mis":"M1-2-u4-X02"}],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["6 + 6 = 12, 6 + 7 = 13 — 더하는 수가 1 커지면 합도 1 커져요.","그래서 6 + 8 = 14 예요.","10을 만들어 확인하면 6 + 4 + 4 = 14 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#5','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',2,'sa','auto','5 + 8 = 13 이에요. 그러면 8 + 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C4","difficulty":2,"kind":"sa","stem":"5 + 8 = 13 이에요. 그러면 8 + 5 는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["5 + 8 과 8 + 5 는 같은 두 수를 모으는 거예요.","그래서 8 + 5 도 13이에요.","두 수를 바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#6','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',2,'blank','auto','9 + 4 = 13 이에요. 그러면 9 + 5 = □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":6,"concept":"M1-2-u4-C4","difficulty":2,"kind":"blank","stem":"9 + 4 = 13 이에요. 그러면 9 + 5 = □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"14","correct":true},{"t":"13","mis":"M1-2-u4-X06"},{"t":"15","mis":"M1-2-u4-X06"}],"explanation":["더하는 수 4가 5로 1 커졌어요.","그래서 합도 1 커져 14예요.","15는 2가 커진 답이에요 — 1만 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#7','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',2,'match','auto','합이 같은 식끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C4","difficulty":2,"kind":"match","stem":"합이 같은 식끼리 선으로 이어 보세요.","pairs":[{"l":"7 + 6","r":"8 + 5"},{"l":"9 + 2","r":"5 + 6"},{"l":"8 + 8","r":"9 + 7"}],"explanation":["7 + 6 = 13, 8 + 5 = 13 이에요.","9 + 2 = 11, 5 + 6 = 11 이에요.","8 + 8 = 16, 9 + 7 = 16 — 한 수가 1 커지고 다른 수가 1 작아지면 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#8','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',2,'data','auto','표를 보세요. 합이 같은 식이 나란히 있어요. 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":8,"concept":"M1-2-u4-C4","difficulty":2,"kind":"data","stem":"표를 보세요. 합이 같은 식이 나란히 있어요. 빈칸에 알맞은 수를 고르세요.","asset":{"type":"expr_grid","rows":[["4 + 9","5 + 8","6 + 7"],["13",null,"13"]]},"options":[{"t":"13","correct":true},{"t":"14","mis":"M1-2-u4-X06"},{"t":"12","mis":"M1-2-u4-X06"}],"explanation":["4 + 9 = 13, 6 + 7 = 13 이에요.","5 + 8 은 앞 수가 1 커지고 뒤 수가 1 작아져 합은 그대로 13이에요.","한쪽이 커진 만큼 다른 쪽이 작아지면 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_basic#9','math',1,2,'u4','L05','g1_2_math_u4_L05_basic','lesson_basic','M1-2-u4-C4',2,'mc','auto','합이 같은 식끼리 짝 지은 것은 어느 것인가요?',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":9,"concept":"M1-2-u4-C4","difficulty":2,"kind":"mc","stem":"합이 같은 식끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"6 + 9 와 8 + 7","correct":true},{"t":"7 + 7 과 7 + 8","mis":"M1-2-u4-X06"},{"t":"5 + 9 와 9 + 4","mis":"M1-2-u4-X06"}],"explanation":["6 + 9 = 15, 8 + 7 = 15 예요.","7 + 7 = 14, 7 + 8 = 15 로 1 달라요.","5 + 9 = 14, 9 + 4 = 13 으로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
