INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#3','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',3,'ox','auto','8 + 6 = 14 이면 8 + 7 = 14 입니다.',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":3,"concept":"M1-2-u4-C4","difficulty":3,"kind":"ox","stem":"8 + 6 = 14 이면 8 + 7 = 14 입니다.","answer":"X","reason_options":[{"t":"더하는 수가 1 커지면 합도 1 커져 15니까","correct":true},{"t":"더하는 수가 커져도 합은 그대로니까","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["8 + 6 = 14 는 맞아요.","6이 7로 1 커졌으니 합도 1 커져 15예요.","더하는 수가 커지면 합도 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#4','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',3,'data','auto','표를 보세요. 합이 16인 식은 어느 것인가요?',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":4,"concept":"M1-2-u4-C4","difficulty":3,"kind":"data","stem":"표를 보세요. 합이 16인 식은 어느 것인가요?","asset":{"type":"expr_grid","rows":[["7 + 8","8 + 8","9 + 8"],["15","16","17"]]},"options":[{"t":"8 + 8","correct":true},{"t":"7 + 8","mis":"M1-2-u4-X06"},{"t":"9 + 8","mis":"M1-2-u4-X06"}],"explanation":["7 + 8 = 15, 8 + 8 = 16, 9 + 8 = 17 이에요.","앞 수가 1씩 커지면 합도 1씩 커져요.","합이 16인 식은 8 + 8 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#5','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',3,'sa','auto','7 + 9 = 16 이에요. 그러면 9 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C4","difficulty":3,"kind":"sa","stem":"7 + 9 = 16 이에요. 그러면 9 + 7 은 얼마인가요? 숫자로 쓰세요.","answer":["16"],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["7 + 9 와 9 + 7 은 순서만 바뀐 식이에요.","바꾸어 더해도 합은 같아 16이에요.","계산하지 않아도 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#6','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',3,'match','auto','앞 식을 알면 바로 알 수 있는 식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u4-C4","difficulty":3,"kind":"match","stem":"앞 식을 알면 바로 알 수 있는 식을 선으로 이어 보세요.","pairs":[{"l":"8 + 3 = 11 이면","r":"8 + 4 = 12"},{"l":"9 + 9 = 18 이면","r":"9 + 8 = 17"},{"l":"6 + 5 = 11 이면","r":"5 + 6 = 11"}],"explanation":["8 + 4 는 8 + 3 보다 1 크니까 12예요.","9 + 8 은 9 + 9 보다 1 작으니까 17이에요.","5 + 6 은 6 + 5 를 바꾸어 더한 것이라 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#7','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',3,'error','auto','민수가 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#8','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',4,'sa','auto','5 + 6 = 11, 5 + 7 = 12 예요. 그러면 5 + 9 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C4","difficulty":4,"kind":"sa","stem":"5 + 6 = 11, 5 + 7 = 12 예요. 그러면 5 + 9 는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["더하는 수가 1 커질 때마다 합도 1 커져요.","5 + 8 = 13, 5 + 9 = 14 예요.","7에서 9까지 2 커졌으니 12에서 2 커진 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#9','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',4,'mc','auto','7 + 7 = 14 를 알면 계산하지 않고 바로 알 수 있는 식은 어느 것인가요?',ARRAY['M1-2-u4-X06']::text[],false,'{"seq":9,"concept":"M1-2-u4-C4","difficulty":4,"kind":"mc","stem":"7 + 7 = 14 를 알면 계산하지 않고 바로 알 수 있는 식은 어느 것인가요?","options":[{"t":"7 + 8","correct":true},{"t":"8 + 9","mis":"M1-2-u4-X06"},{"t":"7 + 3","mis":"M1-2-u4-X06"}],"explanation":["7 + 8 은 7 + 7 보다 1 크니까 15예요.","8 + 9 는 두 수가 모두 달라 7 + 7 로는 바로 알 수 없어요.","7 + 3 은 10이 되는 짝으로 따로 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L05_challenge#10','math',1,2,'u4','L05','g1_2_math_u4_L05_challenge','lesson_challenge','M1-2-u4-C4',4,'essay','teacher','9 + 5 = 14 를 알면 9 + 6 과 5 + 9 를 계산하지 않고도 알 수 있어요. 각각 얼마인지, 그리고 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C4","difficulty":4,"kind":"essay","stem":"9 + 5 = 14 를 알면 9 + 6 과 5 + 9 를 계산하지 않고도 알 수 있어요. 각각 얼마인지, 그리고 그 까닭을 쓰세요.","answer_guide":"① 9 + 6 = 15 — 더하는 수가 1 커져 합도 1 커진다 ② 5 + 9 = 14 — 바꾸어 더해도 합은 같다 ③ 두 까닭이 규칙으로 쓰여 있으면 만점, 답만 쓰면 절반","explanation":["9 + 6 은 9 + 5 보다 더하는 수가 1 커서 15예요.","5 + 9 는 9 + 5 를 바꾸어 더한 것이라 14예요.","규칙을 알면 다시 세지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#1','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',1,'sa','auto','요구르트병이 13개 있었는데 5개를 마셨어요. 13부터 5번 거꾸로 세면 얼마가 남나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C5","difficulty":1,"kind":"sa","stem":"요구르트병이 13개 있었는데 5개를 마셨어요. 13부터 5번 거꾸로 세면 얼마가 남나요? 숫자로 쓰세요.","asset":{"type":"count_on","start":13,"steps":5,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["13은 이미 있는 수예요 — 12부터 세어요.","12, 11, 10, 9, 8 — 5번 거꾸로 세면 8이에요.","13부터 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#2','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',1,'mc','auto','수 구슬 12개를 옮긴 뒤 4개를 되돌렸어요. 옮겨 둔 구슬은 몇 개 남았나요?',ARRAY['M1-2-u4-X08','M1-2-u4-X09']::text[],false,'{"seq":2,"concept":"M1-2-u4-C5","difficulty":1,"kind":"mc","stem":"수 구슬 12개를 옮긴 뒤 4개를 되돌렸어요. 옮겨 둔 구슬은 몇 개 남았나요?","asset":{"type":"beads","moved":12,"cross":4},"options":[{"t":"8","correct":true},{"t":"9","mis":"M1-2-u4-X08"},{"t":"16","mis":"M1-2-u4-X09"}],"explanation":["12개에서 4개를 되돌리면 뺄셈이에요 — 12 − 4.","11, 10, 9, 8 — 4번 거꾸로 세면 8이에요.","12를 함께 세면 9, 더하면 16이 나와 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#3','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',1,'mc','auto','그림을 보세요. 우유갑은 요구르트병보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":3,"concept":"M1-2-u4-C5","difficulty":1,"kind":"mc","stem":"그림을 보세요. 우유갑은 요구르트병보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"우유갑","item":"🥛","n":11},{"label":"요구르트병","item":"🧃","n":7}]},"options":[{"t":"4","correct":true},{"t":"18","mis":"M1-2-u4-X09"},{"t":"5","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 7쌍이 되고 우유갑 4개가 남아요.","11 − 7 = 4 예요.","18은 두 수를 더한 것 — 「더 많은 수」는 뺄셈으로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#4','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',1,'mc','auto','꽃 14송이 가운데 6송이를 친구에게 주었어요. 남은 꽃을 구하는 식으로 바른 것은 어느 것인가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],false,'{"seq":4,"concept":"M1-2-u4-C5","difficulty":1,"kind":"mc","stem":"꽃 14송이 가운데 6송이를 친구에게 주었어요. 남은 꽃을 구하는 식으로 바른 것은 어느 것인가요?","options":[{"t":"14 − 6 = 8","correct":true},{"t":"14 + 6 = 20","mis":"M1-2-u4-X09"},{"t":"14 − 6 = 9","mis":"M1-2-u4-X08"}],"explanation":["주고 남은 것은 뺄셈이에요 — 14 − 6.","13부터 6번 거꾸로 세면 8이에요.","14를 함께 세면 9가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#5','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',2,'ox','auto','15부터 6번 거꾸로 세면 10입니다.',ARRAY['M1-2-u4-X08']::text[],true,'{"seq":5,"concept":"M1-2-u4-C5","difficulty":2,"kind":"ox","stem":"15부터 6번 거꾸로 세면 10입니다.","asset":{"type":"count_on","start":15,"steps":6,"dir":"down"},"answer":"X","reason_options":[{"t":"14부터 6번 세면 9니까","correct":true},{"t":"15부터 세어도 되니까","mis":"M1-2-u4-X08"}],"variant_rule":{"counton":{"dir":"down"}},"explanation":["15는 이미 있는 수라 14부터 세어요.","14, 13, 12, 11, 10, 9 — 답은 9예요.","15를 함께 세면 10이 나와요 — 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#6','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',2,'sa','auto','저금통에 동전이 12개 있었는데 5개를 꺼냈어요. 남은 동전은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u4-C5","difficulty":2,"kind":"sa","stem":"저금통에 동전이 12개 있었는데 5개를 꺼냈어요. 남은 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["꺼내고 남은 것은 뺄셈이에요 — 12 − 5.","11, 10, 9, 8, 7 — 5번 거꾸로 세면 7이에요.","12는 이미 있는 수라 11부터 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#7','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',2,'blank','auto','우유갑이 15개, 요구르트병이 8개 있어요. 우유갑이 □개 더 많아요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],false,'{"seq":7,"concept":"M1-2-u4-C5","difficulty":2,"kind":"blank","stem":"우유갑이 15개, 요구르트병이 8개 있어요. 우유갑이 □개 더 많아요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"7","correct":true},{"t":"23","mis":"M1-2-u4-X09"},{"t":"8","mis":"M1-2-u4-X08"}],"explanation":["하나씩 짝 지으면 8쌍이 되고 우유갑 7개가 남아요.","15 − 8 = 7 이에요.","두 수를 더한 23은 「더 많은 수」가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#8','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',2,'match','auto','상황과 뺄셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C5","difficulty":2,"kind":"match","stem":"상황과 뺄셈식을 선으로 이어 보세요.","pairs":[{"l":"사탕 11개 중 4개를 먹었어요","r":"11 − 4"},{"l":"연필 16자루 중 9자루를 주었어요","r":"16 − 9"},{"l":"꽃 13송이는 5송이보다 몇 송이 더 많나요","r":"13 − 5"}],"explanation":["먹고 남은 것, 주고 남은 것은 뺄셈이에요.","「몇 개 더 많은지」도 큰 수에서 작은 수를 빼요.","11 − 4 = 7, 16 − 9 = 7, 13 − 5 = 8 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#9','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 빨간 꽃은 노란 꽃보다 몇 송이 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":9,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 빨간 꽃은 노란 꽃보다 몇 송이 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"빨간 꽃","item":"🌹","n":12},{"label":"노란 꽃","item":"🌼","n":9}]},"options":[{"t":"3","correct":true},{"t":"21","mis":"M1-2-u4-X09"},{"t":"4","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 9쌍이 되고 빨간 꽃 3송이가 남아요.","12 − 9 = 3 이에요.","21은 두 수를 더한 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_basic#10','math',1,2,'u4','L06','g1_2_math_u4_L06_basic','lesson_basic','M1-2-u4-C5',3,'error','auto','민수가 「사탕 13개는 7개보다 몇 개 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#1','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',2,'sa','auto','14부터 6번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C5","difficulty":2,"kind":"sa","stem":"14부터 6번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":14,"steps":6,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["14는 이미 있는 수예요 — 13부터 세어요.","13, 12, 11, 10, 9, 8 — 6번 거꾸로 세면 8이에요.","14부터 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#2','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 연필은 지우개보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":2,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 연필은 지우개보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"연필","item":"✏️","n":13},{"label":"지우개","item":"🧽","n":8}]},"options":[{"t":"5","correct":true},{"t":"21","mis":"M1-2-u4-X09"},{"t":"6","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 8쌍이 되고 연필 5자루가 남아요.","13 − 8 = 5 예요.","21은 두 수를 더한 것 — 「더 많은 수」는 뺄셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#3','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',3,'ox','auto','17 − 9 를 거꾸로 세어 구할 때 16부터 셉니다.',ARRAY['M1-2-u4-X08']::text[],false,'{"seq":3,"concept":"M1-2-u4-C5","difficulty":3,"kind":"ox","stem":"17 − 9 를 거꾸로 세어 구할 때 16부터 셉니다.","answer":"O","reason_options":[{"t":"17은 이미 있는 수니까","correct":true},{"t":"17부터 세어야 하니까","mis":"M1-2-u4-X08"}],"explanation":["17은 이미 있는 수라 세지 않아요.","16, 15, 14, 13, 12, 11, 10, 9, 8 — 9번 세면 8이에요.","17부터 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#4','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',3,'sa','auto','수 구슬 16개를 옮긴 뒤 9개를 되돌렸어요. 옮겨 둔 구슬은 몇 개 남았나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u4-C5","difficulty":3,"kind":"sa","stem":"수 구슬 16개를 옮긴 뒤 9개를 되돌렸어요. 옮겨 둔 구슬은 몇 개 남았나요? 숫자로 쓰세요.","asset":{"type":"beads","moved":16,"cross":9},"answer":["7"],"explanation":["16 − 9 예요.","15부터 9번 거꾸로 세면 7이에요.","되돌린 구슬을 × 표로 지우고 남은 것을 세어도 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#5','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',3,'mc','auto','「12와 4 가운데 어느 것이 몇 개 더 많은지」를 구하는 식은 어느 것인가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X10']::text[],false,'{"seq":5,"concept":"M1-2-u4-C5","difficulty":3,"kind":"mc","stem":"「12와 4 가운데 어느 것이 몇 개 더 많은지」를 구하는 식은 어느 것인가요?","options":[{"t":"12 − 4","correct":true},{"t":"12 + 4","mis":"M1-2-u4-X09"},{"t":"4 − 12","mis":"M1-2-u4-X10"}],"explanation":["더 많은 수는 큰 수에서 작은 수를 빼요 — 12 − 4 = 8.","더하면 전체 개수가 돼요.","작은 수에서 큰 수를 뺄 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#6','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',3,'error','auto','지우가 15 − 7 을 이렇게 세었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#7','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',3,'match','auto','뺄셈식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C5","difficulty":3,"kind":"match","stem":"뺄셈식과 답을 선으로 이어 보세요.","pairs":[{"l":"13 − 5","r":"8"},{"l":"16 − 7","r":"9"},{"l":"11 − 4","r":"7"}],"explanation":["13 − 5 는 12부터 5번 거꾸로 세어 8이에요.","16 − 7 = 9, 11 − 4 = 7 이에요.","거꾸로 셀 때 처음 수는 세지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#8','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',4,'sa','auto','동전이 몇 개 있었는데 6개를 꺼냈더니 8개가 남았어요. 처음에 동전은 몇 개였나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C5","difficulty":4,"kind":"sa","stem":"동전이 몇 개 있었는데 6개를 꺼냈더니 8개가 남았어요. 처음에 동전은 몇 개였나요? 숫자로 쓰세요.","answer":["14"],"explanation":["남은 8개에 꺼낸 6개를 다시 넣으면 처음 수예요.","8 + 6 = 14 예요.","14 − 6 = 8 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#9','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',4,'mc','auto','우유갑이 14개, 요구르트병이 6개 있어요. 요구르트병이 우유갑만큼 되려면 몇 개가 더 있어야 하나요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],false,'{"seq":9,"concept":"M1-2-u4-C5","difficulty":4,"kind":"mc","stem":"우유갑이 14개, 요구르트병이 6개 있어요. 요구르트병이 우유갑만큼 되려면 몇 개가 더 있어야 하나요?","options":[{"t":"8","correct":true},{"t":"20","mis":"M1-2-u4-X09"},{"t":"9","mis":"M1-2-u4-X08"}],"explanation":["하나씩 짝을 지으면 6쌍이 되고 우유갑 8개가 남아요.","남은 만큼 요구르트병이 더 있어야 해요 — 14 − 6 = 8.","20은 두 수를 더한 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L06_challenge#10','math',1,2,'u4','L06','g1_2_math_u4_L06_challenge','lesson_challenge','M1-2-u4-C5',4,'essay','teacher','13 − 8 을 거꾸로 세기와 짝 짓기, 두 가지 방법으로 구하는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C5","difficulty":4,"kind":"essay","stem":"13 − 8 을 거꾸로 세기와 짝 짓기, 두 가지 방법으로 구하는 방법을 쓰세요.","answer_guide":"① 거꾸로 세기: 12부터 8번 세어 5 (13은 세지 않음) ② 짝 짓기: 13개와 8개를 하나씩 짝 지어 남는 5개 ③ 두 답이 같다 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["거꾸로 세기는 13 다음 12부터 8번 세어 5예요.","짝 짓기는 하나씩 짝 지어 8쌍을 만들고 남는 5개를 세요.","방법이 달라도 답은 5로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#1','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',1,'mc','auto','14 − 9 를 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X12']::text[],true,'{"seq":1,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"14 − 9 를 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":14,"right":9,"op":"-","split":"right","parts":[4,5]},"options":[{"t":"5","correct":true},{"t":"15","mis":"M1-2-u4-X10"},{"t":"10","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["9를 4와 5로 갈라 낱개 4를 먼저 빼요 — 14 − 4 = 10.","10 − 5 = 5 예요.","15는 9 − 4 로 거꾸로 뺀 답이에요 — 답은 14보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#2','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',1,'sa','auto','13 − 7 을 계산해요. 낱개 3을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u4-C6","difficulty":1,"kind":"sa","stem":"13 − 7 을 계산해요. 낱개 3을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":13,"right":7,"op":"-","split":"right","parts":[3,null]},"answer":["4"],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["7을 낱개 3과 4로 갈라요.","13 − 3 = 10, 10 − 4 = 6 이에요.","낱개를 뺀 뒤 남은 수를 한 번 더 빼야 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#3','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',1,'mc','auto','십 배열판을 보세요. 15 − 8 을 계산하려고 낱개 5를 먼저 × 표로 지웠어요. 10에서 몇을 더 빼야 하나요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":3,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 15 − 8 을 계산하려고 낱개 5를 먼저 × 표로 지웠어요. 10에서 몇을 더 빼야 하나요?","asset":{"type":"ten_frames2","top":10,"bottom":5,"cross":8,"cross_from":"bottom"},"options":[{"t":"3","correct":true},{"t":"8","mis":"M1-2-u4-X03"},{"t":"5","mis":"M1-2-u4-X03"}],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["8을 낱개 5와 3으로 갈라요.","15 − 5 = 10 다음에 10 − 3 = 7 이에요.","지운 5는 이미 뺐으니 남은 3만 더 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#4','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',1,'mc','auto','12 − 5 를 계산해요. 낱개 2를 먼저 빼려면 5를 2와 몇으로 갈라야 하나요?',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],true,'{"seq":4,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"12 − 5 를 계산해요. 낱개 2를 먼저 빼려면 5를 2와 몇으로 갈라야 하나요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u4-X05"},{"t":"5","mis":"M1-2-u4-X03"}],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["5를 낱개와 같은 2와 3으로 갈라요.","12 − 2 = 10, 10 − 3 = 7 이에요.","가르는 수는 낱개 2를 보고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#5','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',2,'sa','auto','16 − 7 은 얼마인가요? 10을 이용해 계산하고 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C6","difficulty":2,"kind":"sa","stem":"16 − 7 은 얼마인가요? 10을 이용해 계산하고 숫자로 쓰세요.","answer":["9"],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["7을 6과 1로 갈라 낱개 6을 먼저 빼요 — 16 − 6 = 10.","10 − 1 = 9 예요.","낱개를 뺀 뒤 남은 1을 꼭 더 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#6','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',2,'ox','auto','11 − 4 에서 낱개 1을 먼저 빼고, 이어서 3을 더 빼면 7입니다.',ARRAY['M1-2-u4-X12']::text[],true,'{"seq":6,"concept":"M1-2-u4-C6","difficulty":2,"kind":"ox","stem":"11 − 4 에서 낱개 1을 먼저 빼고, 이어서 3을 더 빼면 7입니다.","answer":"O","reason_options":[{"t":"4를 1과 3으로 갈랐으니까","correct":true},{"t":"낱개만 빼면 끝이니까","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["4를 낱개 1과 3으로 갈라요.","11 − 1 = 10, 10 − 3 = 7 이에요 — 맞아요.","낱개만 빼고 끝내면 10이 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#7','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',2,'blank','auto','15 − 6 = 15 − 5 − □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X12']::text[],false,'{"seq":7,"concept":"M1-2-u4-C6","difficulty":2,"kind":"blank","stem":"15 − 6 = 15 − 5 − □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"1","correct":true},{"t":"6","mis":"M1-2-u4-X05"},{"t":"10","mis":"M1-2-u4-X12"}],"explanation":["6을 낱개 5와 1로 갈라요.","15 − 5 = 10, 10 − 1 = 9 예요.","5는 이미 뺐으니 남은 1만 더 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_basic#8','math',1,2,'u4','L07','g1_2_math_u4_L07_basic','lesson_basic','M1-2-u4-C6',2,'match','auto','뺄셈식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C6","difficulty":2,"kind":"match","stem":"뺄셈식과 답을 선으로 이어 보세요.","pairs":[{"l":"13 − 6","r":"7"},{"l":"12 − 7","r":"5"},{"l":"17 − 8","r":"9"}],"explanation":["13 − 6 은 13 − 3 − 3 = 7 이에요.","12 − 7 은 12 − 2 − 5 = 5 예요.","17 − 8 은 17 − 7 − 1 = 9 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
