INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_challenge#3','math',1,2,'u4','L07','g1_2_math_u4_L07_challenge','lesson_challenge','M1-2-u4-C6',3,'ox','auto','12 − 8 = 16 입니다.',ARRAY['M1-2-u4-X10']::text[],true,'{"seq":3,"concept":"M1-2-u4-C6","difficulty":3,"kind":"ox","stem":"12 − 8 = 16 입니다.","answer":"X","reason_options":[{"t":"낱개 2를 먼저 빼고 6을 더 빼면 4니까","correct":true},{"t":"낱개끼리는 큰 수에서 작은 수를 빼면 되니까","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["8을 2와 6으로 갈라 12 − 2 = 10, 10 − 6 = 4 예요.","16은 8 − 2 로 거꾸로 뺀 답이에요.","12에서 빼면 답은 12보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
