INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_challenge#7','math',1,2,'u4','L07','g1_2_math_u4_L07_challenge','lesson_challenge','M1-2-u4-C6',3,'match','auto','뺄셈식과 낱개를 먼저 빼는 방법을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C6","difficulty":3,"kind":"match","stem":"뺄셈식과 낱개를 먼저 빼는 방법을 선으로 이어 보세요.","pairs":[{"l":"14 − 5","r":"14 − 4 − 1"},{"l":"13 − 8","r":"13 − 3 − 5"},{"l":"16 − 7","r":"16 − 6 − 1"}],"explanation":["14 − 5 는 5를 4와 1로 갈라 14 − 4 − 1 이에요.","13 − 8 은 8을 3과 5로 갈라 13 − 3 − 5 예요.","16 − 7 은 7을 6과 1로 갈라 16 − 6 − 1 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_challenge#8','math',1,2,'u4','L07','g1_2_math_u4_L07_challenge','lesson_challenge','M1-2-u4-C6',4,'sa','auto','15 − □ = 7 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C6","difficulty":4,"kind":"sa","stem":"15 − □ = 7 이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["8"],"explanation":["15에서 낱개 5를 빼면 10, 10에서 3을 빼면 7이에요.","그래서 뺀 수는 5와 3을 모은 8이에요.","15 − 8 = 7 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_challenge#9','math',1,2,'u4','L07','g1_2_math_u4_L07_challenge','lesson_challenge','M1-2-u4-C6',4,'mc','auto','13 − 7 과 차가 같은 식은 어느 것인가요?',ARRAY['M1-2-u4-X13']::text[],false,'{"seq":9,"concept":"M1-2-u4-C6","difficulty":4,"kind":"mc","stem":"13 − 7 과 차가 같은 식은 어느 것인가요?","options":[{"t":"14 − 8","correct":true},{"t":"13 − 6","mis":"M1-2-u4-X13"},{"t":"12 − 7","mis":"M1-2-u4-X13"}],"explanation":["13 − 7 = 6, 14 − 8 = 6 이에요.","13 − 6 = 7, 12 − 7 = 5 로 달라요.","두 수가 함께 1 커지면 차는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L07_challenge#10','math',1,2,'u4','L07','g1_2_math_u4_L07_challenge','lesson_challenge','M1-2-u4-C6',4,'essay','teacher','12 − 7 을 낱개를 먼저 빼는 방법으로 계산하고, 7을 왜 2와 5로 갈랐는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C6","difficulty":4,"kind":"essay","stem":"12 − 7 을 낱개를 먼저 빼는 방법으로 계산하고, 7을 왜 2와 5로 갈랐는지도 쓰세요.","answer_guide":"① 12 − 2 = 10 ② 10 − 5 = 5 ③ 낱개가 2라서 7을 2와 5로 갈랐다 — 셋 다 있으면 만점, 답 5만 쓰면 절반","explanation":["낱개 2를 먼저 빼려고 7을 2와 5로 갈라요.","12 − 2 = 10, 10 − 5 = 5 예요.","가르는 수는 처음 수의 낱개를 보고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#1','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',1,'mc','auto','15를 10과 5로 갈라 10에서 7을 뺐어요. 15 − 7 은 얼마인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],true,'{"seq":1,"concept":"M1-2-u4-C7","difficulty":1,"kind":"mc","stem":"15를 10과 5로 갈라 10에서 7을 뺐어요. 15 − 7 은 얼마인가요?","asset":{"type":"split_tree","left":15,"right":7,"op":"-","split":"left","parts":[10,5]},"options":[{"t":"8","correct":true},{"t":"3","mis":"M1-2-u4-X11"},{"t":"12","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["15를 10과 5로 갈라 10에서 7을 빼요 — 10 − 7 = 3.","3에 남은 낱개 5를 더하면 8이에요.","3에서 멈추면 낱개가 빠지고, 7 − 5 로 거꾸로 빼면 12가 나와 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#2','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',1,'sa','auto','십 배열판을 보세요. 윗판 10에서 8을 × 표로 지웠어요. 13 − 8 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u4-C7","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 윗판 10에서 8을 × 표로 지웠어요. 13 − 8 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"ten_frames2","top":10,"bottom":3,"cross":8,"cross_from":"top"},"answer":["5"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 8을 빼면 2가 남아요.","2에 아랫판 낱개 3을 더하면 5예요.","윗판에서 빼고 아랫판을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#3','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',1,'mc','auto','16 − 9 를 10에서 빼기로 계산해요. 10 − 9 = 1 다음에 무엇을 해야 하나요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],false,'{"seq":3,"concept":"M1-2-u4-C7","difficulty":1,"kind":"mc","stem":"16 − 9 를 10에서 빼기로 계산해요. 10 − 9 = 1 다음에 무엇을 해야 하나요?","options":[{"t":"1에 낱개 6을 더해요 — 7","correct":true},{"t":"1이 답이에요","mis":"M1-2-u4-X11"},{"t":"6에서 9를 못 빼니 9 − 6 을 해요","mis":"M1-2-u4-X10"}],"explanation":["16을 10과 6으로 갈라 10에서 9를 빼면 1이에요.","남은 낱개 6을 더해 1 + 6 = 7 이에요.","1에서 멈추면 낱개 6이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#4','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',1,'mc','auto','14 − 6 을 10에서 빼기로 계산하려고 해요. 14를 10과 몇으로 갈라야 하나요?',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":4,"concept":"M1-2-u4-C7","difficulty":1,"kind":"mc","stem":"14 − 6 을 10에서 빼기로 계산하려고 해요. 14를 10과 몇으로 갈라야 하나요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-2-u4-X03"},{"t":"8","mis":"M1-2-u4-X03"}],"explanation":["14는 10개씩 묶음 1개와 낱개 4개예요.","그래서 14를 10과 4로 갈라요.","10 − 6 = 4, 4 + 4 = 8 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#5','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',2,'sa','auto','12 − 9 는 얼마인가요? 10에서 빼서 계산하고 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C7","difficulty":2,"kind":"sa","stem":"12 − 9 는 얼마인가요? 10에서 빼서 계산하고 숫자로 쓰세요.","answer":["3"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["12를 10과 2로 갈라 10에서 9를 빼요 — 10 − 9 = 1.","1에 남은 낱개 2를 더하면 3이에요.","1에서 멈추면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#6','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',2,'ox','auto','13 − 8 = 15 입니다.',ARRAY['M1-2-u4-X10']::text[],true,'{"seq":6,"concept":"M1-2-u4-C7","difficulty":2,"kind":"ox","stem":"13 − 8 = 15 입니다.","answer":"X","reason_options":[{"t":"10에서 8을 빼고 낱개 3을 더하면 5니까","correct":true},{"t":"낱개끼리는 큰 수에서 작은 수를 빼면 되니까","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["13에서 8을 빼면 답은 13보다 작아야 해요.","10 − 8 = 2, 2 + 3 = 5 예요.","8 − 3 = 5 로 거꾸로 빼면 15가 나와요 — 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#7','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',2,'blank','auto','17 − 9 = 10 − 9 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X11','M1-2-u4-X03']::text[],false,'{"seq":7,"concept":"M1-2-u4-C7","difficulty":2,"kind":"blank","stem":"17 − 9 = 10 − 9 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"7","correct":true},{"t":"1","mis":"M1-2-u4-X11"},{"t":"9","mis":"M1-2-u4-X03"}],"explanation":["17을 10과 7로 갈라요.","10 − 9 = 1 에 낱개 7을 더해요 — 8.","더하는 수는 처음 수의 낱개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#8','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',2,'match','auto','뺄셈식과 답을 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C7","difficulty":2,"kind":"match","stem":"뺄셈식과 답을 선으로 이어 보세요.","pairs":[{"l":"14 − 9","r":"5"},{"l":"11 − 7","r":"4"},{"l":"18 − 9","r":"9"}],"explanation":["14 − 9 는 10 − 9 = 1, 1 + 4 = 5 예요.","11 − 7 은 10 − 7 = 3, 3 + 1 = 4 예요.","18 − 9 는 10 − 9 = 1, 1 + 8 = 9 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_basic#9','math',1,2,'u4','L08','g1_2_math_u4_L08_basic','lesson_basic','M1-2-u4-C7',2,'mc','auto','12를 10과 2로 갈랐어요. 12 − 7 은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X11']::text[],true,'{"seq":9,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"12를 10과 2로 갈랐어요. 12 − 7 은 얼마인가요?","asset":{"type":"split_tree","left":12,"right":7,"op":"-","split":"left","parts":[10,2]},"options":[{"t":"5","correct":true},{"t":"15","mis":"M1-2-u4-X10"},{"t":"3","mis":"M1-2-u4-X11"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 7을 빼면 3이에요.","3에 남은 낱개 2를 더하면 5예요.","7 − 2 로 거꾸로 빼면 15가 나와요 — 답은 12보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
