INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#1','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',2,'sa','auto','16을 10과 6으로 갈라 10에서 8을 뺐어요. 16 − 8 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C7","difficulty":2,"kind":"sa","stem":"16을 10과 6으로 갈라 10에서 8을 뺐어요. 16 − 8 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":16,"right":8,"op":"-","split":"left","parts":[10,6]},"answer":["8"],"variant_rule":{"takeaway":{"ask":"diff","way":"both"}},"explanation":["10 − 8 = 2 예요.","2에 남은 낱개 6을 더하면 8이에요.","10에서 빼고 낱개를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#2','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',2,'mc','auto','십 배열판을 보세요. 14 − 9 는 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X11']::text[],true,'{"seq":2,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 14 − 9 는 얼마인가요?","asset":{"type":"ten_frames2","top":10,"bottom":4,"cross":9,"cross_from":"top"},"options":[{"t":"5","correct":true},{"t":"15","mis":"M1-2-u4-X10"},{"t":"1","mis":"M1-2-u4-X11"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["윗판 10에서 9를 지우면 1이 남아요.","1에 아랫판 낱개 4를 더하면 5예요.","1에서 멈추면 낱개가 빠지고, 거꾸로 빼면 15가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#3','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',3,'ox','auto','11 − 5 = 6 입니다.',ARRAY['M1-2-u4-X10']::text[],true,'{"seq":3,"concept":"M1-2-u4-C7","difficulty":3,"kind":"ox","stem":"11 − 5 = 6 입니다.","answer":"O","reason_options":[{"t":"10 − 5 = 5, 5 + 1 = 6 이니까","correct":true},{"t":"5 − 1 = 4 니까 14","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"both"}},"explanation":["11을 10과 1로 갈라요.","10 − 5 = 5, 5 + 1 = 6 이에요 — 맞아요.","5 − 1 로 거꾸로 빼면 14가 되어 11보다 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#4','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',3,'mc','auto','13 − 9 를 낱개 먼저 빼기(13 − 3 − 6)와 10에서 빼기(10 − 9 + 3), 두 방법으로 계산했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X12']::text[],false,'{"seq":4,"concept":"M1-2-u4-C7","difficulty":3,"kind":"mc","stem":"13 − 9 를 낱개 먼저 빼기(13 − 3 − 6)와 10에서 빼기(10 − 9 + 3), 두 방법으로 계산했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 방법 모두 답이 4로 같아요","correct":true},{"t":"10에서 먼저 빼면 답은 1이에요","mis":"M1-2-u4-X11"},{"t":"낱개를 먼저 빼면 답은 10이에요","mis":"M1-2-u4-X12"}],"explanation":["13 − 3 = 10, 10 − 6 = 4 예요.","10 − 9 = 1, 1 + 3 = 4 예요.","방법이 달라도 13에서 9를 빼는 것이라 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#5','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',3,'sa','auto','18 − 9 는 얼마인가요? 10에서 빼서 계산하고 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C7","difficulty":3,"kind":"sa","stem":"18 − 9 는 얼마인가요? 10에서 빼서 계산하고 숫자로 쓰세요.","answer":["9"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["18을 10과 8로 갈라 10 − 9 = 1 이에요.","1에 낱개 8을 더하면 9예요.","1에서 멈추면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#6','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',3,'error','auto','민수가 14 − 8 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#7','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',3,'match','auto','뺄셈식과 계산 방법을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u4-C7","difficulty":3,"kind":"match","stem":"뺄셈식과 계산 방법을 선으로 이어 보세요.","pairs":[{"l":"15 − 9 를 10에서 먼저 빼면","r":"10 − 9 + 5"},{"l":"12 − 6 을 낱개 먼저 빼면","r":"12 − 2 − 4"},{"l":"17 − 8 을 10에서 먼저 빼면","r":"10 − 8 + 7"}],"explanation":["10에서 먼저 빼면 10 − 빼는 수에 낱개를 더해요.","낱개를 먼저 빼면 낱개를 뺀 뒤 남은 수를 더 빼요.","15 − 9 = 6, 12 − 6 = 6, 17 − 8 = 9 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#8','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',4,'sa','auto','어떤 수에서 8을 뺐더니 9가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C7","difficulty":4,"kind":"sa","stem":"어떤 수에서 8을 뺐더니 9가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["뺀 8을 9에 다시 더하면 처음 수예요.","9 + 8 = 17 이에요.","17 − 8 = 9 로 확인해요 — 10 − 8 = 2, 2 + 7 = 9."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#9','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',4,'mc','auto','16 − 9 = 7 을 바르게 설명한 것은 어느 것인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X11']::text[],false,'{"seq":9,"concept":"M1-2-u4-C7","difficulty":4,"kind":"mc","stem":"16 − 9 = 7 을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"10 − 9 = 1, 1 + 6 = 7","correct":true},{"t":"9 − 6 = 3, 10 + 3 = 13","mis":"M1-2-u4-X10"},{"t":"10 − 9 = 1 이 답","mis":"M1-2-u4-X11"}],"explanation":["16을 10과 6으로 갈라 10에서 9를 빼요.","10 − 9 = 1 에 낱개 6을 더해 7이에요.","거꾸로 빼거나 1에서 멈추면 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L08_challenge#10','math',1,2,'u4','L08','g1_2_math_u4_L08_challenge','lesson_challenge','M1-2-u4-C7',4,'essay','teacher','15 − 6 을 10에서 빼는 방법으로 계산하고, 6 − 5 로 계산하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C7","difficulty":4,"kind":"essay","stem":"15 − 6 을 10에서 빼는 방법으로 계산하고, 6 − 5 로 계산하면 안 되는 까닭을 쓰세요.","answer_guide":"① 10 − 6 = 4 ② 4 + 5 = 9 ③ 6 − 5 로 하면 답이 15보다 커지거나(11) 뺄셈이 아니게 된다는 까닭 — 셋 다 있으면 만점, 답 9만 쓰면 절반","explanation":["15를 10과 5로 갈라 10에서 6을 빼면 4예요.","4에 낱개 5를 더해 9예요.","작은 수에서 큰 수를 거꾸로 빼면 뺐는데 답이 커져 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#1','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',1,'sa','auto','표를 보세요. 12 − 3 = 9 예요. 그러면 12 − 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C8","difficulty":1,"kind":"sa","stem":"표를 보세요. 12 − 3 = 9 예요. 그러면 12 − 4 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["12 − 3","12 − 4"],["9",null]]},"answer":["8"],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["12 − 3 = 9 예요. 빼는 수 3이 4로 1 커졌어요.","더 많이 빼니까 차는 1 작아져 8이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#2','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',1,'mc','auto','13 − 4 = 9 예요. 그러면 14 − 5 는 얼마인가요?',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":2,"concept":"M1-2-u4-C8","difficulty":1,"kind":"mc","stem":"13 − 4 = 9 예요. 그러면 14 − 5 는 얼마인가요?","options":[{"t":"9","correct":true},{"t":"10","mis":"M1-2-u4-X13"},{"t":"8","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["빼어지는 수와 빼는 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 9예요.","14 − 4 − 1 = 9 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#3','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',1,'mc','auto','7 + 7 = 14 예요. 그러면 14 − 7 은 얼마인가요?',ARRAY['M1-2-u4-X14']::text[],true,'{"seq":3,"concept":"M1-2-u4-C8","difficulty":1,"kind":"mc","stem":"7 + 7 = 14 예요. 그러면 14 − 7 은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"21","mis":"M1-2-u4-X14"},{"t":"8","mis":"M1-2-u4-X14"}],"variant_rule":{"pattern":{"kind":"family"}},"explanation":["7과 7을 모으면 14예요.","14에서 7을 빼면 남는 것은 7이에요.","덧셈식을 알면 뺄셈식도 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#4','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',1,'ox','auto','11 − 2 = 9 이면 11 − 3 = 8 입니다.',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":4,"concept":"M1-2-u4-C8","difficulty":1,"kind":"ox","stem":"11 − 2 = 9 이면 11 − 3 = 8 입니다.","answer":"O","reason_options":[{"t":"빼는 수가 1 커지면 차는 1 작아지니까","correct":true},{"t":"빼는 수가 커지면 차도 커지니까","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["11 − 2 = 9 예요.","빼는 수가 2에서 3으로 1 커져 차는 1 작아진 8이에요 — 맞아요.","11 − 2, 11 − 3, 11 − 4 줄을 그리면 남는 것이 줄어드는 것이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#5','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',2,'sa','auto','15 − 6 = 9 예요. 그러면 16 − 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C8","difficulty":2,"kind":"sa","stem":"15 − 6 = 9 예요. 그러면 16 − 7 은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["15 − 6 에서 두 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 9예요.","16 − 6 = 10, 10 − 1 = 9 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#6','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',2,'blank','auto','8 + 6 = 14 예요. 그러면 14 − 8 = □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X14']::text[],false,'{"seq":6,"concept":"M1-2-u4-C8","difficulty":2,"kind":"blank","stem":"8 + 6 = 14 예요. 그러면 14 − 8 = □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"6","correct":true},{"t":"22","mis":"M1-2-u4-X14"},{"t":"8","mis":"M1-2-u4-X14"}],"explanation":["8과 6을 모으면 14예요.","14에서 8을 빼면 6이 남아요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#7','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',2,'data','auto','표를 보세요. 차가 같은 식이 나란히 있어요. 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X13']::text[],false,'{"seq":7,"concept":"M1-2-u4-C8","difficulty":2,"kind":"data","stem":"표를 보세요. 차가 같은 식이 나란히 있어요. 빈칸에 알맞은 수를 고르세요.","asset":{"type":"expr_grid","rows":[["11 − 4","12 − 5","13 − 6"],["7",null,"7"]]},"options":[{"t":"7","correct":true},{"t":"8","mis":"M1-2-u4-X13"},{"t":"6","mis":"M1-2-u4-X13"}],"explanation":["11 − 4 = 7, 13 − 6 = 7 이에요.","12 − 5 는 두 수가 함께 1씩 커졌으니 차는 그대로 7이에요.","두 수가 함께 커지면 차는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#8','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',2,'match','auto','차가 같은 식끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C8","difficulty":2,"kind":"match","stem":"차가 같은 식끼리 선으로 이어 보세요.","pairs":[{"l":"12 − 5","r":"13 − 6"},{"l":"15 − 8","r":"16 − 9"},{"l":"11 − 3","r":"14 − 6"}],"explanation":["12 − 5 = 7, 13 − 6 = 7 이에요.","15 − 8 = 7, 16 − 9 = 7 이에요.","11 − 3 = 8, 14 − 6 = 8 — 두 수가 함께 3 커져도 차는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_basic#9','math',1,2,'u4','L09','g1_2_math_u4_L09_basic','lesson_basic','M1-2-u4-C8',2,'mc','auto','표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":9,"concept":"M1-2-u4-C8","difficulty":2,"kind":"mc","stem":"표를 보세요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","asset":{"type":"expr_grid","rows":[["13 − 4","13 − 5","13 − 6"],["9","8",null]]},"options":[{"t":"7","correct":true},{"t":"8","mis":"M1-2-u4-X13"},{"t":"9","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["13 − 4 = 9, 13 − 5 = 8 — 빼는 수가 1 커지면 차는 1 작아져요.","그래서 13 − 6 = 7 이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
