INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_challenge#5','math',1,2,'u4','L09','g1_2_math_u4_L09_challenge','lesson_challenge','M1-2-u4-C8',3,'mc','auto','차가 같은 식끼리 짝 지은 것은 어느 것인가요?',ARRAY['M1-2-u4-X13']::text[],false,'{"seq":5,"concept":"M1-2-u4-C8","difficulty":3,"kind":"mc","stem":"차가 같은 식끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"12 − 4 와 13 − 5","correct":true},{"t":"12 − 4 와 12 − 5","mis":"M1-2-u4-X13"},{"t":"12 − 4 와 13 − 4","mis":"M1-2-u4-X13"}],"explanation":["12 − 4 = 8, 13 − 5 = 8 이에요.","12 − 5 = 7 — 빼는 수만 커지면 차는 작아져요.","13 − 4 = 9 — 빼어지는 수만 커지면 차는 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
