INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_challenge#8','math',1,2,'u4','L09','g1_2_math_u4_L09_challenge','lesson_challenge','M1-2-u4-C8',4,'sa','auto','표를 보세요. 11 − 2 = 9, 12 − 3 = 9, 13 − 4 = 9 예요. 그러면 14 − 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u4-C8","difficulty":4,"kind":"sa","stem":"표를 보세요. 11 − 2 = 9, 12 − 3 = 9, 13 − 4 = 9 예요. 그러면 14 − 5 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["11 − 2","12 − 3","13 − 4","14 − 5"],["9","9","9",null]]},"answer":["9"],"explanation":["두 수가 함께 1씩 커지고 있어요.","함께 커지면 차는 그대로 9예요.","14 − 4 = 10, 10 − 1 = 9 로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_challenge#9','math',1,2,'u4','L09','g1_2_math_u4_L09_challenge','lesson_challenge','M1-2-u4-C8',4,'mc','auto','7 + 6 = 13 을 알면 만들 수 있는 뺄셈식 두 개는 어느 것인가요?',ARRAY['M1-2-u4-X14']::text[],false,'{"seq":9,"concept":"M1-2-u4-C8","difficulty":4,"kind":"mc","stem":"7 + 6 = 13 을 알면 만들 수 있는 뺄셈식 두 개는 어느 것인가요?","options":[{"t":"13 − 7 = 6, 13 − 6 = 7","correct":true},{"t":"13 + 7 = 20, 13 + 6 = 19","mis":"M1-2-u4-X14"},{"t":"7 − 6 = 1, 13 − 1 = 12","mis":"M1-2-u4-X14"}],"explanation":["7과 6을 모으면 13이에요.","13에서 7을 빼면 6, 13에서 6을 빼면 7이에요.","덧셈식 하나로 뺄셈식 두 개를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_L09_challenge#10','math',1,2,'u4','L09','g1_2_math_u4_L09_challenge','lesson_challenge','M1-2-u4-C8',4,'essay','teacher','8 + 9 = 17 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C8","difficulty":4,"kind":"essay","stem":"8 + 9 = 17 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.","answer_guide":"① 17 − 8 = 9 ② 17 − 9 = 8 ③ 8과 9를 모은 것이 17이라 17에서 한 수를 빼면 다른 수가 남는다는 까닭 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["8과 9를 모으면 17이에요.","17에서 8을 빼면 9, 17에서 9를 빼면 8이에요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#1','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C1',1,'sa','auto','7부터 5번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":1,"kind":"sa","stem":"7부터 5번 이어 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":7,"steps":5,"dir":"up"},"answer":["12"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["7은 이미 있는 수예요 — 8부터 세어요.","5번 이어 세면 12예요.","7부터 함께 세면 11이 되어 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#2','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C1',1,'mc','auto','십 배열판을 보세요. 8개가 있었는데 5개를 더 놓았어요. 모두 몇 개인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 8개가 있었는데 5개를 더 놓았어요. 모두 몇 개인가요?","asset":{"type":"ten_frames2","top":8,"bottom":3,"add":2},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 8에 2를 더 놓아 10이 되었어요.","아랫판에 남은 3을 놓았으니 10과 3, 13이에요.","10에서 멈추거나 3만 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#3','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C1',1,'match','auto','상황과 덧셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":1,"kind":"match","stem":"상황과 덧셈식을 선으로 이어 보세요.","pairs":[{"l":"우유갑 8개와 6개를 모았어요","r":"8 + 6"},{"l":"꽃 7송이와 9송이가 피었어요","r":"7 + 9"},{"l":"동전 5개에 7개를 더 넣었어요","r":"5 + 7"}],"explanation":["모으거나 더 넣는 상황은 덧셈이에요.","앞의 수와 뒤의 수를 그대로 식에 써요.","8 + 6 = 14, 7 + 9 = 16, 5 + 7 = 12 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#4','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C2',1,'mc','auto','6 + 9 를 계산해요. 6과 더해 10을 만들려면 9에서 얼마를 떼어 내야 하나요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"6 + 9 를 계산해요. 6과 더해 10을 만들려면 9에서 얼마를 떼어 내야 하나요?","asset":{"type":"split_tree","left":6,"right":9,"op":"+","split":"right","parts":[null,5]},"options":[{"t":"4","correct":true},{"t":"5","mis":"M1-2-u4-X03"},{"t":"6","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["6과 모아 10이 되는 수는 4예요.","6 + 4 = 10 이니까 9에서 4를 떼어 내요.","남은 5는 10에 더해 15가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#5','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C2',2,'sa','auto','8 + 7 을 계산해요. 8과 더해 10을 만들려고 7을 2와 몇으로 갈라야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"8 + 7 을 계산해요. 8과 더해 10을 만들려고 7을 2와 몇으로 갈라야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":8,"right":7,"op":"+","split":"right","parts":[2,null]},"answer":["5"],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["8과 2를 더하면 10이에요.","7에서 2를 떼면 5가 남아요.","7은 2와 5로 갈라져요 — 10 + 5 = 15."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#6','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C2',2,'blank','auto','8 + 5 = 8 + 2 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":6,"concept":"M1-2-u4-C2","difficulty":2,"kind":"blank","stem":"8 + 5 = 8 + 2 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-2-u4-X05"},{"t":"2","mis":"M1-2-u4-X03"}],"explanation":["8과 더해 10이 되도록 5를 2와 3으로 갈랐어요.","2는 이미 썼으니 남은 3을 더해요.","5를 그대로 또 더하면 안 돼요 — 10 + 3 = 13."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#7','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C2',3,'error','auto','지우가 6 + 9 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#8','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C3',2,'mc','auto','9 + 4 를 9를 갈라서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"9 + 4 를 9를 갈라서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":9,"right":4,"op":"+","split":"left","parts":[6,3]},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["4와 모아 10이 되는 수는 6이에요 — 그래서 9를 6과 3으로 갈라요.","4 + 6 = 10, 10 + 3 = 13 예요.","앞 수를 갈라도 10을 만들고 남은 수를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#9','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C3',3,'ox','auto','7 + 8 을 계산할 때 7을 갈라도 되고 8을 갈라도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":3,"kind":"ox","stem":"7 + 8 을 계산할 때 7을 갈라도 되고 8을 갈라도 됩니다.","answer":"O","reason_options":[{"t":"어느 쪽이든 10이 되게 가르면 되니까","correct":true},{"t":"뒤에 있는 수만 갈라야 하니까","mis":"M1-2-u4-X03"}],"explanation":["8과 모아 10이 되도록 7을 2와 5로 갈라도 돼요 — 10 + 5 = 15.","7과 모아 10이 되도록 8을 3과 5로 갈라도 돼요 — 10 + 5 = 15.","어느 수를 갈라도 답은 15로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#10','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C3',4,'essay','teacher','5 + 8 을 5를 갈라서 계산하는 방법과 8을 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C3","difficulty":4,"kind":"essay","stem":"5 + 8 을 5를 갈라서 계산하는 방법과 8을 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.","answer_guide":"① 5를 갈라 8 + 2 = 10, 10 + 3 = 13 ② 8을 갈라 5 + 5 = 10, 10 + 3 = 13 ③ 둘 다 10을 만들고 남은 수를 더하므로 같다는 까닭 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["5를 가르면 8과 모아 10이 되는 2를 떼어 8 + 2 + 3 = 13 예요.","8을 가르면 5와 모아 10이 되는 5를 떼어 5 + 5 + 3 = 13 예요.","어느 쪽이든 10을 만들고 남은 수를 더하니 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#11','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C4',1,'sa','auto','표를 보세요. 8 + 3 = 11 이에요. 그러면 8 + 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M1-2-u4-C4","difficulty":1,"kind":"sa","stem":"표를 보세요. 8 + 3 = 11 이에요. 그러면 8 + 4 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["8 + 3","8 + 4"],["11",null]]},"answer":["12"],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["8 + 3 = 11 이에요. 더하는 수 3이 4로 1 커졌어요.","그래서 합도 1 커져 12예요.","다시 세지 않아도 규칙으로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#12','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C4',2,'mc','auto','표를 보세요. 7 + 7 = 14 이에요. 그러면 7 + 8 은 얼마인가요?',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":12,"concept":"M1-2-u4-C4","difficulty":2,"kind":"mc","stem":"표를 보세요. 7 + 7 = 14 이에요. 그러면 7 + 8 은 얼마인가요?","asset":{"type":"expr_grid","rows":[["7 + 7","7 + 8"],["14",null]]},"options":[{"t":"15","correct":true},{"t":"14","mis":"M1-2-u4-X06"},{"t":"16","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"double"}},"explanation":["7 + 8 은 7 + 7 보다 1 큰 수를 더해요.","그래서 14보다 1 큰 15예요.","같은 수를 더한 답에 1을 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#13','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C4',3,'ox','auto','9 + 4 와 4 + 9 의 합은 같습니다.',ARRAY['M1-2-u4-X07']::text[],true,'{"seq":13,"concept":"M1-2-u4-C4","difficulty":3,"kind":"ox","stem":"9 + 4 와 4 + 9 의 합은 같습니다.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"순서가 바뀌면 합도 달라지니까","mis":"M1-2-u4-X07"}],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["9 + 4 = 13, 4 + 9 = 13 예요.","두 무리를 좌우로 바꿔 놓아도 전체 개수는 같아요.","바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#14','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C5',1,'sa','auto','13부터 5번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-2-u4-C5","difficulty":1,"kind":"sa","stem":"13부터 5번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":13,"steps":5,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["13은 이미 있는 수예요 — 12부터 세어요.","5번 거꾸로 세면 8이에요.","13부터 함께 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#15','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 우유갑은 요구르트병보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":15,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 우유갑은 요구르트병보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"우유갑","item":"🥛","n":11},{"label":"요구르트병","item":"🧃","n":7}]},"options":[{"t":"4","correct":true},{"t":"18","mis":"M1-2-u4-X09"},{"t":"5","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 7쌍이 되고 우유갑 4개가 남아요.","11 − 7 = 4 예요.","18은 두 수를 더한 것 — 「더 많은 수」는 뺄셈으로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#16','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C5',3,'error','auto','민수가 「사탕 13개는 7개보다 몇 개 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#17','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C6',1,'mc','auto','14 − 9 를 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X12']::text[],true,'{"seq":17,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"14 − 9 를 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":14,"right":9,"op":"-","split":"right","parts":[4,5]},"options":[{"t":"5","correct":true},{"t":"15","mis":"M1-2-u4-X10"},{"t":"10","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["9를 4와 5로 갈라 낱개 4를 먼저 빼요 — 14 − 4 = 10.","10 − 5 = 5 예요.","15는 9 − 4 로 거꾸로 뺀 답이에요 — 답은 14보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#18','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C6',2,'sa','auto','16 − 7 을 계산해요. 낱개 6을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u4-C6","difficulty":2,"kind":"sa","stem":"16 − 7 을 계산해요. 낱개 6을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":16,"right":7,"op":"-","split":"right","parts":[6,null]},"answer":["1"],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["7을 낱개 6과 1로 갈라요.","16 − 6 = 10, 10 − 1 = 9 예요.","낱개를 뺀 뒤 남은 수를 한 번 더 빼야 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#19','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C6',3,'ox','auto','십 배열판을 보세요. 15 − 7 = 8 입니다.',ARRAY['M1-2-u4-X12']::text[],true,'{"seq":19,"concept":"M1-2-u4-C6","difficulty":3,"kind":"ox","stem":"십 배열판을 보세요. 15 − 7 = 8 입니다.","asset":{"type":"ten_frames2","top":10,"bottom":5,"cross":7,"cross_from":"bottom"},"answer":"O","reason_options":[{"t":"낱개를 먼저 빼고 남은 수를 더 뺐으니까","correct":true},{"t":"낱개만 빼면 끝이니까","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["아랫판 낱개 5를 먼저 지우고 윗판에서 2를 더 지워요.","15 − 5 = 10, 10 − 2 = 8 예요 — 맞아요.","낱개만 지우고 멈추면 10이 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#20','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C7',1,'sa','auto','13을 10과 3으로 갈라 10에서 8을 뺐어요. 13 − 8 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u4-C7","difficulty":1,"kind":"sa","stem":"13을 10과 3으로 갈라 10에서 8을 뺐어요. 13 − 8 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":13,"right":8,"op":"-","split":"left","parts":[10,3]},"answer":["5"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10 − 8 = 2 예요.","2에 남은 낱개 3을 더하면 5예요.","2에서 멈추면 낱개 3이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#21','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C7',2,'mc','auto','십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 14 − 9 는 얼마인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],true,'{"seq":21,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 14 − 9 는 얼마인가요?","asset":{"type":"ten_frames2","top":10,"bottom":4,"cross":9,"cross_from":"top"},"options":[{"t":"5","correct":true},{"t":"1","mis":"M1-2-u4-X11"},{"t":"15","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 9를 빼면 1이 남아요.","1에 아랫판 낱개 4를 더하면 5예요.","1에서 멈추면 낱개가 빠지고, 거꾸로 빼면 15가 나와요 — 둘 다 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#22','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C7',4,'error','auto','지우가 15 − 7 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#23','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C8',2,'sa','auto','표를 보세요. 12 − 3 = 9 이에요. 그러면 12 − 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M1-2-u4-C8","difficulty":2,"kind":"sa","stem":"표를 보세요. 12 − 3 = 9 이에요. 그러면 12 − 4 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["12 − 3","12 − 4"],["9",null]]},"answer":["8"],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["12 − 3 = 9 이에요. 빼는 수 3이 4로 1 커졌어요.","더 많이 빼니까 차는 1 작아져 8이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#24','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C8',3,'mc','auto','표를 보세요. 13 − 5 = 8 이에요. 그러면 14 − 6 은 얼마인가요?',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":24,"concept":"M1-2-u4-C8","difficulty":3,"kind":"mc","stem":"표를 보세요. 13 − 5 = 8 이에요. 그러면 14 − 6 은 얼마인가요?","asset":{"type":"expr_grid","rows":[["13 − 5","14 − 6"],["8",null]]},"options":[{"t":"8","correct":true},{"t":"9","mis":"M1-2-u4-X13"},{"t":"7","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["13 − 5 = 8 이에요. 빼어지는 수와 빼는 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 8이에요.","9는 차도 커진다고 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_a#25','math',1,2,'u4','review','g1_2_math_u4_review_a','unit_review','M1-2-u4-C8',4,'essay','teacher','7 + 8 = 15 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u4-C8","difficulty":4,"kind":"essay","stem":"7 + 8 = 15 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.","answer_guide":"① 15 − 7 = 8 ② 15 − 8 = 7 ③ 7과 8을 모은 것이 15라서 15에서 한 수를 빼면 다른 수가 남는다는 까닭 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["7과 8을 모으면 15예요.","15에서 7을 빼면 8, 15에서 8을 빼면 7이에요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#1','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C1',1,'sa','auto','8부터 4번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":1,"kind":"sa","stem":"8부터 4번 이어 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":8,"steps":4,"dir":"up"},"answer":["12"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["8은 이미 있는 수예요 — 9부터 세어요.","4번 이어 세면 12예요.","8부터 함께 세면 11이 되어 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#2','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C1',1,'mc','auto','십 배열판을 보세요. 7개가 있었는데 6개를 더 놓았어요. 모두 몇 개인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 7개가 있었는데 6개를 더 놓았어요. 모두 몇 개인가요?","asset":{"type":"ten_frames2","top":7,"bottom":3,"add":3},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 7에 3을 더 놓아 10이 되었어요.","아랫판에 남은 3을 놓았으니 10과 3, 13이에요.","10에서 멈추거나 3만 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#3','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C1',1,'match','auto','상황과 덧셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":1,"kind":"match","stem":"상황과 덧셈식을 선으로 이어 보세요.","pairs":[{"l":"우유갑 9개와 5개를 모았어요","r":"9 + 5"},{"l":"꽃 6송이와 8송이가 피었어요","r":"6 + 8"},{"l":"동전 4개에 7개를 더 넣었어요","r":"4 + 7"}],"explanation":["모으거나 더 넣는 상황은 덧셈이에요.","앞의 수와 뒤의 수를 그대로 식에 써요.","9 + 5 = 14, 6 + 8 = 14, 4 + 7 = 11 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#4','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C2',1,'mc','auto','7 + 5 를 계산해요. 7과 더해 10을 만들려면 5에서 얼마를 떼어 내야 하나요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"7 + 5 를 계산해요. 7과 더해 10을 만들려면 5에서 얼마를 떼어 내야 하나요?","asset":{"type":"split_tree","left":7,"right":5,"op":"+","split":"right","parts":[null,2]},"options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u4-X03"},{"t":"7","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["7과 모아 10이 되는 수는 3이에요.","7 + 3 = 10 이니까 5에서 3을 떼어 내요.","남은 2는 10에 더해 12가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#5','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C2',2,'sa','auto','6 + 8 을 계산해요. 6과 더해 10을 만들려고 8을 4와 몇으로 갈라야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"6 + 8 을 계산해요. 6과 더해 10을 만들려고 8을 4와 몇으로 갈라야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":6,"right":8,"op":"+","split":"right","parts":[4,null]},"answer":["4"],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["6과 4를 더하면 10이에요.","8에서 4를 떼면 4가 남아요.","8은 4와 4로 갈라져요 — 10 + 4 = 14."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#6','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C2',2,'blank','auto','9 + 3 = 9 + 1 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":6,"concept":"M1-2-u4-C2","difficulty":2,"kind":"blank","stem":"9 + 3 = 9 + 1 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"2","correct":true},{"t":"3","mis":"M1-2-u4-X05"},{"t":"1","mis":"M1-2-u4-X03"}],"explanation":["9와 더해 10이 되도록 3을 1과 2로 갈랐어요.","1은 이미 썼으니 남은 2를 더해요.","3을 그대로 또 더하면 안 돼요 — 10 + 2 = 12."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#7','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C2',3,'error','auto','민수가 8 + 6 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#8','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C3',2,'mc','auto','8 + 5 를 8을 갈라서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"8 + 5 를 8을 갈라서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":8,"right":5,"op":"+","split":"left","parts":[5,3]},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["5와 모아 10이 되는 수는 5예요 — 그래서 8을 5와 3으로 갈라요.","5 + 5 = 10, 10 + 3 = 13 예요.","앞 수를 갈라도 10을 만들고 남은 수를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#9','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C3',3,'ox','auto','9 + 6 을 계산할 때 9를 갈라도 되고 6을 갈라도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":3,"kind":"ox","stem":"9 + 6 을 계산할 때 9를 갈라도 되고 6을 갈라도 됩니다.","answer":"O","reason_options":[{"t":"어느 쪽이든 10이 되게 가르면 되니까","correct":true},{"t":"뒤에 있는 수만 갈라야 하니까","mis":"M1-2-u4-X03"}],"explanation":["6과 모아 10이 되도록 9를 4와 5로 갈라도 돼요 — 10 + 5 = 15.","9와 모아 10이 되도록 6을 1과 5로 갈라도 돼요 — 10 + 5 = 15.","어느 수를 갈라도 답은 15로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#10','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C3',4,'essay','teacher','6 + 7 을 6을 갈라서 계산하는 방법과 7을 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C3","difficulty":4,"kind":"essay","stem":"6 + 7 을 6을 갈라서 계산하는 방법과 7을 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.","answer_guide":"① 6을 갈라 7 + 3 = 10, 10 + 3 = 13 ② 7을 갈라 6 + 4 = 10, 10 + 3 = 13 ③ 둘 다 10을 만들고 남은 수를 더하므로 같다는 까닭 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["6을 가르면 7과 모아 10이 되는 3을 떼어 7 + 3 + 3 = 13 예요.","7을 가르면 6과 모아 10이 되는 4를 떼어 6 + 4 + 3 = 13 예요.","어느 쪽이든 10을 만들고 남은 수를 더하니 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#11','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C4',1,'sa','auto','표를 보세요. 7 + 5 = 12 이에요. 그러면 7 + 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M1-2-u4-C4","difficulty":1,"kind":"sa","stem":"표를 보세요. 7 + 5 = 12 이에요. 그러면 7 + 6 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["7 + 5","7 + 6"],["12",null]]},"answer":["13"],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["7 + 5 = 12 이에요. 더하는 수 5가 6으로 1 커졌어요.","그래서 합도 1 커져 13이에요.","다시 세지 않아도 규칙으로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#12','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C4',2,'mc','auto','표를 보세요. 8 + 8 = 16 이에요. 그러면 8 + 9 는 얼마인가요?',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":12,"concept":"M1-2-u4-C4","difficulty":2,"kind":"mc","stem":"표를 보세요. 8 + 8 = 16 이에요. 그러면 8 + 9 는 얼마인가요?","asset":{"type":"expr_grid","rows":[["8 + 8","8 + 9"],["16",null]]},"options":[{"t":"17","correct":true},{"t":"16","mis":"M1-2-u4-X06"},{"t":"18","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"double"}},"explanation":["8 + 9 은 8 + 8 보다 1 큰 수를 더해요.","그래서 16보다 1 큰 17이에요.","같은 수를 더한 답에 1을 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#13','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C4',3,'ox','auto','8 + 6 과 6 + 8 의 합은 같습니다.',ARRAY['M1-2-u4-X07']::text[],true,'{"seq":13,"concept":"M1-2-u4-C4","difficulty":3,"kind":"ox","stem":"8 + 6 과 6 + 8 의 합은 같습니다.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"순서가 바뀌면 합도 달라지니까","mis":"M1-2-u4-X07"}],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["8 + 6 = 14, 6 + 8 = 14 예요.","두 무리를 좌우로 바꿔 놓아도 전체 개수는 같아요.","바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#14','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C5',1,'sa','auto','14부터 6번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-2-u4-C5","difficulty":1,"kind":"sa","stem":"14부터 6번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":14,"steps":6,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["14는 이미 있는 수예요 — 13부터 세어요.","6번 거꾸로 세면 8이에요.","14부터 함께 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#15','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 빨간 꽃은 노란 꽃보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":15,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 빨간 꽃은 노란 꽃보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"빨간 꽃","item":"🌹","n":13},{"label":"노란 꽃","item":"🌼","n":9}]},"options":[{"t":"4","correct":true},{"t":"22","mis":"M1-2-u4-X09"},{"t":"5","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 9쌍이 되고 빨간 꽃 4개가 남아요.","13 − 9 = 4 예요.","22는 두 수를 더한 것 — 「더 많은 수」는 뺄셈으로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#16','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C5',3,'error','auto','지우가 「구슬 12개는 5개보다 몇 개 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#17','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C6',1,'mc','auto','13 − 7 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X12']::text[],true,'{"seq":17,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"13 − 7 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":13,"right":7,"op":"-","split":"right","parts":[3,4]},"options":[{"t":"6","correct":true},{"t":"14","mis":"M1-2-u4-X10"},{"t":"10","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["7을 3과 4로 갈라 낱개 3을 먼저 빼요 — 13 − 3 = 10.","10 − 4 = 6 예요.","14는 7 − 3 로 거꾸로 뺀 답이에요 — 답은 13보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#18','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C6',2,'sa','auto','11 − 5 를 계산해요. 낱개 1을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u4-C6","difficulty":2,"kind":"sa","stem":"11 − 5 를 계산해요. 낱개 1을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":11,"right":5,"op":"-","split":"right","parts":[1,null]},"answer":["4"],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["5를 낱개 1과 4로 갈라요.","11 − 1 = 10, 10 − 4 = 6 예요.","낱개를 뺀 뒤 남은 수를 한 번 더 빼야 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#19','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C6',3,'ox','auto','십 배열판을 보세요. 12 − 8 = 16 입니다.',ARRAY['M1-2-u4-X10']::text[],true,'{"seq":19,"concept":"M1-2-u4-C6","difficulty":3,"kind":"ox","stem":"십 배열판을 보세요. 12 − 8 = 16 입니다.","asset":{"type":"ten_frames2","top":10,"bottom":2,"cross":8,"cross_from":"bottom"},"answer":"X","reason_options":[{"t":"낱개 2를 먼저 빼고 6을 더 빼면 4가니까","correct":true},{"t":"낱개끼리는 큰 수에서 작은 수를 빼면 되니까","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["8을 2와 6으로 갈라 12 − 2 = 10, 10 − 6 = 4 예요.","16은 8 − 2 로 거꾸로 뺀 답이에요.","12에서 빼면 답은 12보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#20','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C7',1,'sa','auto','16을 10과 6으로 갈라 10에서 9를 뺐어요. 16 − 9 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u4-C7","difficulty":1,"kind":"sa","stem":"16을 10과 6으로 갈라 10에서 9를 뺐어요. 16 − 9 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":16,"right":9,"op":"-","split":"left","parts":[10,6]},"answer":["7"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10 − 9 = 1 예요.","1에 남은 낱개 6을 더하면 7이에요.","1에서 멈추면 낱개 6이 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#21','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C7',2,'mc','auto','십 배열판을 보세요. 윗판 10에서 8을 × 표로 지웠어요. 11 − 8 은 얼마인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],true,'{"seq":21,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 윗판 10에서 8을 × 표로 지웠어요. 11 − 8 은 얼마인가요?","asset":{"type":"ten_frames2","top":10,"bottom":1,"cross":8,"cross_from":"top"},"options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u4-X11"},{"t":"17","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 8을 빼면 2가 남아요.","2에 아랫판 낱개 1을 더하면 3이에요.","2에서 멈추면 낱개가 빠지고, 거꾸로 빼면 17이 나와요 — 둘 다 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#22','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C7',4,'error','auto','민수가 13 − 8 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#23','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C8',2,'sa','auto','표를 보세요. 15 − 6 = 9 이에요. 그러면 15 − 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M1-2-u4-C8","difficulty":2,"kind":"sa","stem":"표를 보세요. 15 − 6 = 9 이에요. 그러면 15 − 7 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["15 − 6","15 − 7"],["9",null]]},"answer":["8"],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["15 − 6 = 9 이에요. 빼는 수 6이 7로 1 커졌어요.","더 많이 빼니까 차는 1 작아져 8이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#24','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C8',3,'mc','auto','표를 보세요. 14 − 6 = 8 이에요. 그러면 15 − 7 은 얼마인가요?',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":24,"concept":"M1-2-u4-C8","difficulty":3,"kind":"mc","stem":"표를 보세요. 14 − 6 = 8 이에요. 그러면 15 − 7 은 얼마인가요?","asset":{"type":"expr_grid","rows":[["14 − 6","15 − 7"],["8",null]]},"options":[{"t":"8","correct":true},{"t":"9","mis":"M1-2-u4-X13"},{"t":"7","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["14 − 6 = 8 이에요. 빼어지는 수와 빼는 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 8이에요.","9는 차도 커진다고 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_b#25','math',1,2,'u4','review','g1_2_math_u4_review_b','unit_review','M1-2-u4-C8',4,'essay','teacher','9 + 5 = 14 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u4-C8","difficulty":4,"kind":"essay","stem":"9 + 5 = 14 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.","answer_guide":"① 14 − 9 = 5 ② 14 − 5 = 9 ③ 9와 5를 모은 것이 14라서 14에서 한 수를 빼면 다른 수가 남는다는 까닭 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["9와 5를 모으면 14예요.","14에서 9를 빼면 5, 14에서 5를 빼면 9예요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#1','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C1',1,'sa','auto','6부터 6번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":1,"kind":"sa","stem":"6부터 6번 이어 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":6,"steps":6,"dir":"up"},"answer":["12"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["6은 이미 있는 수예요 — 7부터 세어요.","6번 이어 세면 12예요.","6부터 함께 세면 11이 되어 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#2','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C1',1,'mc','auto','십 배열판을 보세요. 9개가 있었는데 4개를 더 놓았어요. 모두 몇 개인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 9개가 있었는데 4개를 더 놓았어요. 모두 몇 개인가요?","asset":{"type":"ten_frames2","top":9,"bottom":3,"add":1},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 9에 1을 더 놓아 10이 되었어요.","아랫판에 남은 3을 놓았으니 10과 3, 13이에요.","10에서 멈추거나 3만 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#3','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C1',1,'match','auto','상황과 덧셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":1,"kind":"match","stem":"상황과 덧셈식을 선으로 이어 보세요.","pairs":[{"l":"우유갑 7개와 7개를 모았어요","r":"7 + 7"},{"l":"꽃 8송이와 5송이가 피었어요","r":"8 + 5"},{"l":"동전 6개에 9개를 더 넣었어요","r":"6 + 9"}],"explanation":["모으거나 더 넣는 상황은 덧셈이에요.","앞의 수와 뒤의 수를 그대로 식에 써요.","7 + 7 = 14, 8 + 5 = 13, 6 + 9 = 15 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#4','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C2',1,'mc','auto','8 + 6 을 계산해요. 8과 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"8 + 6 을 계산해요. 8과 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요?","asset":{"type":"split_tree","left":8,"right":6,"op":"+","split":"right","parts":[null,4]},"options":[{"t":"2","correct":true},{"t":"4","mis":"M1-2-u4-X03"},{"t":"8","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["8과 모아 10이 되는 수는 2예요.","8 + 2 = 10 이니까 6에서 2를 떼어 내요.","남은 4는 10에 더해 14가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#5','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C2',2,'sa','auto','9 + 7 을 계산해요. 9와 더해 10을 만들려고 7을 1과 몇으로 갈라야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"9 + 7 을 계산해요. 9와 더해 10을 만들려고 7을 1과 몇으로 갈라야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":9,"right":7,"op":"+","split":"right","parts":[1,null]},"answer":["6"],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["9와 1을 더하면 10이에요.","7에서 1을 떼면 6이 남아요.","7은 1과 6으로 갈라져요 — 10 + 6 = 16."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#6','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C2',2,'blank','auto','7 + 4 = 7 + 3 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":6,"concept":"M1-2-u4-C2","difficulty":2,"kind":"blank","stem":"7 + 4 = 7 + 3 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"1","correct":true},{"t":"4","mis":"M1-2-u4-X05"},{"t":"3","mis":"M1-2-u4-X03"}],"explanation":["7과 더해 10이 되도록 4를 3과 1로 갈랐어요.","3은 이미 썼으니 남은 1을 더해요.","4를 그대로 또 더하면 안 돼요 — 10 + 1 = 11."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#7','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C2',3,'error','auto','하늘이 7 + 8 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#8','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C3',2,'mc','auto','7 + 9 를 7을 갈라서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"7 + 9 를 7을 갈라서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":7,"right":9,"op":"+","split":"left","parts":[1,6]},"options":[{"t":"16","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"6","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["9와 모아 10이 되는 수는 1이에요 — 그래서 7을 1과 6으로 갈라요.","9 + 1 = 10, 10 + 6 = 16 예요.","앞 수를 갈라도 10을 만들고 남은 수를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#9','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C3',3,'ox','auto','8 + 7 을 계산할 때 8을 갈라도 되고 7을 갈라도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":3,"kind":"ox","stem":"8 + 7 을 계산할 때 8을 갈라도 되고 7을 갈라도 됩니다.","answer":"O","reason_options":[{"t":"어느 쪽이든 10이 되게 가르면 되니까","correct":true},{"t":"뒤에 있는 수만 갈라야 하니까","mis":"M1-2-u4-X03"}],"explanation":["7과 모아 10이 되도록 8을 3과 5로 갈라도 돼요 — 10 + 5 = 15.","8과 모아 10이 되도록 7을 2와 5로 갈라도 돼요 — 10 + 5 = 15.","어느 수를 갈라도 답은 15로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#10','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C3',4,'essay','teacher','4 + 9 를 4를 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C3","difficulty":4,"kind":"essay","stem":"4 + 9 를 4를 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.","answer_guide":"① 4를 갈라 9 + 1 = 10, 10 + 3 = 13 ② 9를 갈라 4 + 6 = 10, 10 + 3 = 13 ③ 둘 다 10을 만들고 남은 수를 더하므로 같다는 까닭 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["4를 가르면 9와 모아 10이 되는 1을 떼어 9 + 1 + 3 = 13 예요.","9를 가르면 4와 모아 10이 되는 6을 떼어 4 + 6 + 3 = 13 예요.","어느 쪽이든 10을 만들고 남은 수를 더하니 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#11','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C4',1,'sa','auto','표를 보세요. 9 + 2 = 11 이에요. 그러면 9 + 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M1-2-u4-C4","difficulty":1,"kind":"sa","stem":"표를 보세요. 9 + 2 = 11 이에요. 그러면 9 + 3 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["9 + 2","9 + 3"],["11",null]]},"answer":["12"],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["9 + 2 = 11 이에요. 더하는 수 2가 3으로 1 커졌어요.","그래서 합도 1 커져 12예요.","다시 세지 않아도 규칙으로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#12','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C4',2,'mc','auto','표를 보세요. 6 + 6 = 12 이에요. 그러면 6 + 7 은 얼마인가요?',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":12,"concept":"M1-2-u4-C4","difficulty":2,"kind":"mc","stem":"표를 보세요. 6 + 6 = 12 이에요. 그러면 6 + 7 은 얼마인가요?","asset":{"type":"expr_grid","rows":[["6 + 6","6 + 7"],["12",null]]},"options":[{"t":"13","correct":true},{"t":"12","mis":"M1-2-u4-X06"},{"t":"14","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"double"}},"explanation":["6 + 7 은 6 + 6 보다 1 큰 수를 더해요.","그래서 12보다 1 큰 13이에요.","같은 수를 더한 답에 1을 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#13','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C4',3,'ox','auto','7 + 9 와 9 + 7 의 합은 같습니다.',ARRAY['M1-2-u4-X07']::text[],true,'{"seq":13,"concept":"M1-2-u4-C4","difficulty":3,"kind":"ox","stem":"7 + 9 와 9 + 7 의 합은 같습니다.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"순서가 바뀌면 합도 달라지니까","mis":"M1-2-u4-X07"}],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["7 + 9 = 16, 9 + 7 = 16 예요.","두 무리를 좌우로 바꿔 놓아도 전체 개수는 같아요.","바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#14','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C5',1,'sa','auto','12부터 4번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-2-u4-C5","difficulty":1,"kind":"sa","stem":"12부터 4번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":12,"steps":4,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["12는 이미 있는 수예요 — 11부터 세어요.","4번 거꾸로 세면 8이에요.","12부터 함께 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#15','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 연필은 지우개보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":15,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 연필은 지우개보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"연필","item":"✏️","n":12},{"label":"지우개","item":"🧽","n":5}]},"options":[{"t":"7","correct":true},{"t":"17","mis":"M1-2-u4-X09"},{"t":"8","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 5쌍이 되고 연필 7개가 남아요.","12 − 5 = 7 예요.","17은 두 수를 더한 것 — 「더 많은 수」는 뺄셈으로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#16','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C5',3,'error','auto','하늘이 「딱지 15개는 8개보다 몇 개 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#17','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C6',1,'mc','auto','15 − 8 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X12']::text[],true,'{"seq":17,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"15 − 8 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":15,"right":8,"op":"-","split":"right","parts":[5,3]},"options":[{"t":"7","correct":true},{"t":"13","mis":"M1-2-u4-X10"},{"t":"10","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["8을 5와 3으로 갈라 낱개 5를 먼저 빼요 — 15 − 5 = 10.","10 − 3 = 7 예요.","13은 8 − 5 로 거꾸로 뺀 답이에요 — 답은 15보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#18','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C6',2,'sa','auto','13 − 8 을 계산해요. 낱개 3을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u4-C6","difficulty":2,"kind":"sa","stem":"13 − 8 을 계산해요. 낱개 3을 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":13,"right":8,"op":"-","split":"right","parts":[3,null]},"answer":["5"],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["8을 낱개 3과 5로 갈라요.","13 − 3 = 10, 10 − 5 = 5 예요.","낱개를 뺀 뒤 남은 수를 한 번 더 빼야 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#19','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C6',3,'ox','auto','십 배열판을 보세요. 14 − 6 = 8 입니다.',ARRAY['M1-2-u4-X12']::text[],true,'{"seq":19,"concept":"M1-2-u4-C6","difficulty":3,"kind":"ox","stem":"십 배열판을 보세요. 14 − 6 = 8 입니다.","asset":{"type":"ten_frames2","top":10,"bottom":4,"cross":6,"cross_from":"bottom"},"answer":"O","reason_options":[{"t":"낱개를 먼저 빼고 남은 수를 더 뺐으니까","correct":true},{"t":"낱개만 빼면 끝이니까","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["아랫판 낱개 4를 먼저 지우고 윗판에서 2를 더 지워요.","14 − 4 = 10, 10 − 2 = 8 예요 — 맞아요.","낱개만 지우고 멈추면 10이 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#20','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C7',1,'sa','auto','12를 10과 2로 갈라 10에서 7을 뺐어요. 12 − 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u4-C7","difficulty":1,"kind":"sa","stem":"12를 10과 2로 갈라 10에서 7을 뺐어요. 12 − 7 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":12,"right":7,"op":"-","split":"left","parts":[10,2]},"answer":["5"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10 − 7 = 3 예요.","3에 남은 낱개 2를 더하면 5예요.","3에서 멈추면 낱개 2가 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#21','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C7',2,'mc','auto','십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 17 − 9 는 얼마인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],true,'{"seq":21,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 17 − 9 는 얼마인가요?","asset":{"type":"ten_frames2","top":10,"bottom":7,"cross":9,"cross_from":"top"},"options":[{"t":"8","correct":true},{"t":"1","mis":"M1-2-u4-X11"},{"t":"12","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 9를 빼면 1이 남아요.","1에 아랫판 낱개 7을 더하면 8이에요.","1에서 멈추면 낱개가 빠지고, 거꾸로 빼면 12가 나와요 — 둘 다 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#22','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C7',4,'error','auto','하늘이 16 − 9 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#23','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C8',2,'sa','auto','표를 보세요. 13 − 4 = 9 이에요. 그러면 13 − 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M1-2-u4-C8","difficulty":2,"kind":"sa","stem":"표를 보세요. 13 − 4 = 9 이에요. 그러면 13 − 5 는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["13 − 4","13 − 5"],["9",null]]},"answer":["8"],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["13 − 4 = 9 이에요. 빼는 수 4가 5로 1 커졌어요.","더 많이 빼니까 차는 1 작아져 8이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#24','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C8',3,'mc','auto','표를 보세요. 12 − 4 = 8 이에요. 그러면 13 − 5 는 얼마인가요?',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":24,"concept":"M1-2-u4-C8","difficulty":3,"kind":"mc","stem":"표를 보세요. 12 − 4 = 8 이에요. 그러면 13 − 5 는 얼마인가요?","asset":{"type":"expr_grid","rows":[["12 − 4","13 − 5"],["8",null]]},"options":[{"t":"8","correct":true},{"t":"9","mis":"M1-2-u4-X13"},{"t":"7","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["12 − 4 = 8 이에요. 빼어지는 수와 빼는 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 8이에요.","9는 차도 커진다고 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_c#25','math',1,2,'u4','review','g1_2_math_u4_review_c','unit_review','M1-2-u4-C8',4,'essay','teacher','6 + 7 = 13 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u4-C8","difficulty":4,"kind":"essay","stem":"6 + 7 = 13 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.","answer_guide":"① 13 − 6 = 7 ② 13 − 7 = 6 ③ 6과 7을 모은 것이 13라서 13에서 한 수를 빼면 다른 수가 남는다는 까닭 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["6과 7을 모으면 13이에요.","13에서 6을 빼면 7, 13에서 7을 빼면 6이에요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#1','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C1',1,'sa','auto','9부터 3번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u4-C1","difficulty":1,"kind":"sa","stem":"9부터 3번 이어 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":9,"steps":3,"dir":"up"},"answer":["12"],"variant_rule":{"counton":{"dir":"up"}},"explanation":["9는 이미 있는 수예요 — 10부터 세어요.","3번 이어 세면 12예요.","9부터 함께 세면 11이 되어 하나가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#2','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C1',1,'mc','auto','십 배열판을 보세요. 6개가 있었는데 7개를 더 놓았어요. 모두 몇 개인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":2,"concept":"M1-2-u4-C1","difficulty":1,"kind":"mc","stem":"십 배열판을 보세요. 6개가 있었는데 7개를 더 놓았어요. 모두 몇 개인가요?","asset":{"type":"ten_frames2","top":6,"bottom":3,"add":4},"options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"3","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"right"}},"explanation":["윗판은 6에 4를 더 놓아 10이 되었어요.","아랫판에 남은 3을 놓았으니 10과 3, 13이에요.","10에서 멈추거나 3만 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#3','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C1',1,'match','auto','상황과 덧셈식을 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M1-2-u4-C1","difficulty":1,"kind":"match","stem":"상황과 덧셈식을 선으로 이어 보세요.","pairs":[{"l":"우유갑 5개와 8개를 모았어요","r":"5 + 8"},{"l":"꽃 9송이와 6송이가 피었어요","r":"9 + 6"},{"l":"동전 7개에 6개를 더 넣었어요","r":"7 + 6"}],"explanation":["모으거나 더 넣는 상황은 덧셈이에요.","앞의 수와 뒤의 수를 그대로 식에 써요.","5 + 8 = 13, 9 + 6 = 15, 7 + 6 = 13 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#4','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C2',1,'mc','auto','9 + 6 을 계산해요. 9와 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요?',ARRAY['M1-2-u4-X03']::text[],true,'{"seq":4,"concept":"M1-2-u4-C2","difficulty":1,"kind":"mc","stem":"9 + 6 을 계산해요. 9와 더해 10을 만들려면 6에서 얼마를 떼어 내야 하나요?","asset":{"type":"split_tree","left":9,"right":6,"op":"+","split":"right","parts":[null,5]},"options":[{"t":"1","correct":true},{"t":"5","mis":"M1-2-u4-X03"},{"t":"9","mis":"M1-2-u4-X03"}],"variant_rule":{"maketen2":{"ask":"split","which":"right"}},"explanation":["9와 모아 10이 되는 수는 1이에요.","9 + 1 = 10 이니까 6에서 1을 떼어 내요.","남은 5는 10에 더해 15가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#5','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C2',2,'sa','auto','7 + 8 을 계산해요. 7과 더해 10을 만들려고 8을 3과 몇으로 갈라야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-2-u4-C2","difficulty":2,"kind":"sa","stem":"7 + 8 을 계산해요. 7과 더해 10을 만들려고 8을 3과 몇으로 갈라야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":7,"right":8,"op":"+","split":"right","parts":[3,null]},"answer":["5"],"variant_rule":{"maketen2":{"ask":"rest","which":"right"}},"explanation":["7과 3을 더하면 10이에요.","8에서 3을 떼면 5가 남아요.","8은 3과 5로 갈라져요 — 10 + 5 = 15."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#6','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C2',2,'blank','auto','6 + 5 = 6 + 4 + □ 예요. □ 안에 알맞은 수를 고르세요.',ARRAY['M1-2-u4-X05','M1-2-u4-X03']::text[],false,'{"seq":6,"concept":"M1-2-u4-C2","difficulty":2,"kind":"blank","stem":"6 + 5 = 6 + 4 + □ 예요. □ 안에 알맞은 수를 고르세요.","options":[{"t":"1","correct":true},{"t":"5","mis":"M1-2-u4-X05"},{"t":"4","mis":"M1-2-u4-X03"}],"explanation":["6과 더해 10이 되도록 5를 4와 1로 갈랐어요.","4는 이미 썼으니 남은 1을 더해요.","5를 그대로 또 더하면 안 돼요 — 10 + 1 = 11."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#7','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C2',3,'error','auto','보라가 5 + 9 를 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#8','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C3',2,'mc','auto','6 + 8 을 6을 갈라서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X04','M1-2-u4-X02']::text[],true,'{"seq":8,"concept":"M1-2-u4-C3","difficulty":2,"kind":"mc","stem":"6 + 8 을 6을 갈라서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":6,"right":8,"op":"+","split":"left","parts":[2,4]},"options":[{"t":"14","correct":true},{"t":"10","mis":"M1-2-u4-X04"},{"t":"4","mis":"M1-2-u4-X02"}],"variant_rule":{"maketen2":{"ask":"sum","which":"left"}},"explanation":["8과 모아 10이 되는 수는 2예요 — 그래서 6을 2와 4로 갈라요.","8 + 2 = 10, 10 + 4 = 14 예요.","앞 수를 갈라도 10을 만들고 남은 수를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#9','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C3',3,'ox','auto','6 + 9 를 계산할 때 6을 갈라도 되고 9를 갈라도 됩니다.',ARRAY['M1-2-u4-X03']::text[],false,'{"seq":9,"concept":"M1-2-u4-C3","difficulty":3,"kind":"ox","stem":"6 + 9 를 계산할 때 6을 갈라도 되고 9를 갈라도 됩니다.","answer":"O","reason_options":[{"t":"어느 쪽이든 10이 되게 가르면 되니까","correct":true},{"t":"뒤에 있는 수만 갈라야 하니까","mis":"M1-2-u4-X03"}],"explanation":["9와 모아 10이 되도록 6을 1과 5로 갈라도 돼요 — 10 + 5 = 15.","6과 모아 10이 되도록 9를 4와 5로 갈라도 돼요 — 10 + 5 = 15.","어느 수를 갈라도 답은 15로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#10','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C3',4,'essay','teacher','8 + 9 를 8을 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u4-C3","difficulty":4,"kind":"essay","stem":"8 + 9 를 8을 갈라서 계산하는 방법과 9를 갈라서 계산하는 방법을 모두 쓰고, 답이 같은 까닭을 쓰세요.","answer_guide":"① 8을 갈라 9 + 1 = 10, 10 + 7 = 17 ② 9를 갈라 8 + 2 = 10, 10 + 7 = 17 ③ 둘 다 10을 만들고 남은 수를 더하므로 같다는 까닭 — 셋 다 있으면 만점, 한 방법만 쓰면 절반","explanation":["8을 가르면 9와 모아 10이 되는 1을 떼어 9 + 1 + 7 = 17 예요.","9를 가르면 8과 모아 10이 되는 2를 떼어 8 + 2 + 7 = 17 예요.","어느 쪽이든 10을 만들고 남은 수를 더하니 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#11','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C4',1,'sa','auto','표를 보세요. 6 + 6 = 12 이에요. 그러면 6 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M1-2-u4-C4","difficulty":1,"kind":"sa","stem":"표를 보세요. 6 + 6 = 12 이에요. 그러면 6 + 7 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["6 + 6","6 + 7"],["12",null]]},"answer":["13"],"variant_rule":{"pattern":{"kind":"next","op":"add"}},"explanation":["6 + 6 = 12 이에요. 더하는 수 6이 7로 1 커졌어요.","그래서 합도 1 커져 13이에요.","다시 세지 않아도 규칙으로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#12','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C4',2,'mc','auto','표를 보세요. 5 + 5 = 10 이에요. 그러면 5 + 6 은 얼마인가요?',ARRAY['M1-2-u4-X06']::text[],true,'{"seq":12,"concept":"M1-2-u4-C4","difficulty":2,"kind":"mc","stem":"표를 보세요. 5 + 5 = 10 이에요. 그러면 5 + 6 은 얼마인가요?","asset":{"type":"expr_grid","rows":[["5 + 5","5 + 6"],["10",null]]},"options":[{"t":"11","correct":true},{"t":"10","mis":"M1-2-u4-X06"},{"t":"12","mis":"M1-2-u4-X06"}],"variant_rule":{"pattern":{"kind":"double"}},"explanation":["5 + 6 은 5 + 5 보다 1 큰 수를 더해요.","그래서 10보다 1 큰 11이에요.","같은 수를 더한 답에 1을 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#13','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C4',3,'ox','auto','5 + 8 과 8 + 5 의 합은 같습니다.',ARRAY['M1-2-u4-X07']::text[],true,'{"seq":13,"concept":"M1-2-u4-C4","difficulty":3,"kind":"ox","stem":"5 + 8 과 8 + 5 의 합은 같습니다.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"순서가 바뀌면 합도 달라지니까","mis":"M1-2-u4-X07"}],"variant_rule":{"pattern":{"kind":"swap"}},"explanation":["5 + 8 = 13, 8 + 5 = 13 예요.","두 무리를 좌우로 바꿔 놓아도 전체 개수는 같아요.","바꾸어 더해도 합은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#14','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C5',1,'sa','auto','15부터 7번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-2-u4-C5","difficulty":1,"kind":"sa","stem":"15부터 7번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"count_on","start":15,"steps":7,"dir":"down"},"answer":["8"],"variant_rule":{"counton":{"dir":"down"}},"explanation":["15는 이미 있는 수예요 — 14부터 세어요.","7번 거꾸로 세면 8이에요.","15부터 함께 세면 9가 되어 하나가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#15','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C5',2,'mc','auto','그림을 보세요. 동전은 구슬보다 몇 개 더 많은가요?',ARRAY['M1-2-u4-X09','M1-2-u4-X08']::text[],true,'{"seq":15,"concept":"M1-2-u4-C5","difficulty":2,"kind":"mc","stem":"그림을 보세요. 동전은 구슬보다 몇 개 더 많은가요?","asset":{"type":"compare_groups","rows":[{"label":"동전","item":"🪙","n":14},{"label":"구슬","item":"🔵","n":8}]},"options":[{"t":"6","correct":true},{"t":"22","mis":"M1-2-u4-X09"},{"t":"7","mis":"M1-2-u4-X08"}],"variant_rule":{"takeaway":{"ask":"more"}},"explanation":["하나씩 짝을 지으면 8쌍이 되고 동전 6개가 남아요.","14 − 8 = 6 예요.","22는 두 수를 더한 것 — 「더 많은 수」는 뺄셈으로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#16','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C5',3,'error','auto','보라가 「색종이 11개는 4개보다 몇 개 더 많은지」를 이렇게 구했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#17','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C6',1,'mc','auto','12 − 6 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?',ARRAY['M1-2-u4-X10','M1-2-u4-X12']::text[],true,'{"seq":17,"concept":"M1-2-u4-C6","difficulty":1,"kind":"mc","stem":"12 − 6 을 낱개를 먼저 빼서 계산했어요. 답은 얼마인가요?","asset":{"type":"split_tree","left":12,"right":6,"op":"-","split":"right","parts":[2,4]},"options":[{"t":"6","correct":true},{"t":"14","mis":"M1-2-u4-X10"},{"t":"10","mis":"M1-2-u4-X12"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["6을 2와 4로 갈라 낱개 2를 먼저 빼요 — 12 − 2 = 10.","10 − 4 = 6 예요.","14는 6 − 2 로 거꾸로 뺀 답이에요 — 답은 12보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#18','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C6',2,'sa','auto','14 − 6 을 계산해요. 낱개 4를 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u4-C6","difficulty":2,"kind":"sa","stem":"14 − 6 을 계산해요. 낱개 4를 먼저 뺐어요. 얼마를 더 빼야 하나요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":14,"right":6,"op":"-","split":"right","parts":[4,null]},"answer":["2"],"variant_rule":{"takeaway":{"ask":"rest","way":"ones"}},"explanation":["6을 낱개 4와 2로 갈라요.","14 − 4 = 10, 10 − 2 = 8 예요.","낱개를 뺀 뒤 남은 수를 한 번 더 빼야 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#19','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C6',3,'ox','auto','십 배열판을 보세요. 13 − 5 = 12 입니다.',ARRAY['M1-2-u4-X10']::text[],true,'{"seq":19,"concept":"M1-2-u4-C6","difficulty":3,"kind":"ox","stem":"십 배열판을 보세요. 13 − 5 = 12 입니다.","asset":{"type":"ten_frames2","top":10,"bottom":3,"cross":5,"cross_from":"bottom"},"answer":"X","reason_options":[{"t":"낱개 3을 먼저 빼고 2를 더 빼면 8이니까","correct":true},{"t":"낱개끼리는 큰 수에서 작은 수를 빼면 되니까","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ones"}},"explanation":["5를 3과 2로 갈라 13 − 3 = 10, 10 − 2 = 8 예요.","12는 5 − 3 로 거꾸로 뺀 답이에요.","13에서 빼면 답은 13보다 작아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#20','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C7',1,'sa','auto','15를 10과 5로 갈라 10에서 6을 뺐어요. 15 − 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u4-C7","difficulty":1,"kind":"sa","stem":"15를 10과 5로 갈라 10에서 6을 뺐어요. 15 − 6 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"split_tree","left":15,"right":6,"op":"-","split":"left","parts":[10,5]},"answer":["9"],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10 − 6 = 4 예요.","4에 남은 낱개 5를 더하면 9예요.","4에서 멈추면 낱개 5가 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#21','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C7',2,'mc','auto','십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 13 − 9 는 얼마인가요?',ARRAY['M1-2-u4-X11','M1-2-u4-X10']::text[],true,'{"seq":21,"concept":"M1-2-u4-C7","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 윗판 10에서 9를 × 표로 지웠어요. 13 − 9 는 얼마인가요?","asset":{"type":"ten_frames2","top":10,"bottom":3,"cross":9,"cross_from":"top"},"options":[{"t":"4","correct":true},{"t":"1","mis":"M1-2-u4-X11"},{"t":"16","mis":"M1-2-u4-X10"}],"variant_rule":{"takeaway":{"ask":"diff","way":"ten"}},"explanation":["10에서 9를 빼면 1이 남아요.","1에 아랫판 낱개 3을 더하면 4예요.","1에서 멈추면 낱개가 빠지고, 거꾸로 빼면 16이 나와요 — 둘 다 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#22','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C7',4,'error','auto','보라가 12 − 7 을 이렇게 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#23','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C8',2,'sa','auto','표를 보세요. 11 − 2 = 9 이에요. 그러면 11 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M1-2-u4-C8","difficulty":2,"kind":"sa","stem":"표를 보세요. 11 − 2 = 9 이에요. 그러면 11 − 3 은 얼마인가요? 숫자로 쓰세요.","asset":{"type":"expr_grid","rows":[["11 − 2","11 − 3"],["9",null]]},"answer":["8"],"variant_rule":{"pattern":{"kind":"next","op":"sub"}},"explanation":["11 − 2 = 9 이에요. 빼는 수 2가 3으로 1 커졌어요.","더 많이 빼니까 차는 1 작아져 8이에요.","빼는 수가 커지면 남는 것은 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#24','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C8',3,'mc','auto','표를 보세요. 16 − 8 = 8 이에요. 그러면 17 − 9 는 얼마인가요?',ARRAY['M1-2-u4-X13']::text[],true,'{"seq":24,"concept":"M1-2-u4-C8","difficulty":3,"kind":"mc","stem":"표를 보세요. 16 − 8 = 8 이에요. 그러면 17 − 9 는 얼마인가요?","asset":{"type":"expr_grid","rows":[["16 − 8","17 − 9"],["8",null]]},"options":[{"t":"8","correct":true},{"t":"9","mis":"M1-2-u4-X13"},{"t":"7","mis":"M1-2-u4-X13"}],"variant_rule":{"pattern":{"kind":"same"}},"explanation":["16 − 8 = 8 이에요. 빼어지는 수와 빼는 수가 함께 1씩 커졌어요.","함께 커지면 차는 그대로 8이에요.","9는 차도 커진다고 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u4_review_d#25','math',1,2,'u4','review','g1_2_math_u4_review_d','unit_review','M1-2-u4-C8',4,'essay','teacher','8 + 9 = 17 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u4-C8","difficulty":4,"kind":"essay","stem":"8 + 9 = 17 로 만들 수 있는 뺄셈식 두 개를 쓰고, 왜 그렇게 되는지 까닭을 쓰세요.","answer_guide":"① 17 − 8 = 9 ② 17 − 9 = 8 ③ 8과 9를 모은 것이 17라서 17에서 한 수를 빼면 다른 수가 남는다는 까닭 — 셋 다 있으면 만점, 식만 쓰면 절반","explanation":["8과 9를 모으면 17이에요.","17에서 8을 빼면 9, 17에서 9를 빼면 8이에요.","모으기 그림 하나로 덧셈식과 뺄셈식을 나란히 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
